);
create table public.controlled_stock_state_events(
 id uuid primary key,product_id uuid not null references public.catalog_products(id)on delete restrict,
 version integer not null check(version>0),prior_event_id uuid unique references public.controlled_stock_state_events(id)on delete restrict,
 state text not null check(state in('opening_frozen','active','suspended','retired')),
 policy_version_id uuid not null,opening_id uuid,
 actor_id uuid not null references public.profiles(id)on delete restrict,session_id uuid not null,
 reason text not null check(length(reason)between 1 and 2000),recorded_at timestamptz not null default clock_timestamp(),
 foreign key(policy_version_id,product_id)references public.controlled_stock_policy_versions(id,product_id)on delete restrict,
 foreign key(opening_id,product_id)references public.controlled_stock_openings(id,product_id)on delete restrict,
 unique(product_id,version),unique(id,product_id),check((version=1)=(prior_event_id is null)),
 check(state<>'active'or opening_id is not null)
);
create table public.controlled_stock_states(
 product_id uuid primary key references public.catalog_products(id)on delete restrict,
 head_id uuid not null,event_version bigint not null default 0 check(event_version>=0),last_event_id uuid,
 foreign key(head_id,product_id)references public.controlled_stock_state_events(id,product_id)deferrable initially deferred,
 check((event_version=0)=(last_event_id is null))
);
create table public.controlled_stock_preparations(
 id uuid primary key,writer text not null,actor_id uuid not null references public.profiles(id)on delete restrict,
 session_id uuid not null,product_id uuid not null references public.catalog_products(id)on delete restrict,
 policy_version_id uuid not null,state_head_id uuid not null,opening_id uuid not null,
 canonical_arguments jsonb not null check(jsonb_typeof(canonical_arguments)='object'and octet_length(canonical_arguments::text)<=131072),
 context jsonb not null check(jsonb_typeof(context)='object'and octet_length(context::text)<=262144),
 frozen jsonb not null check(jsonb_typeof(frozen)='object'and octet_length(frozen::text)<=1048576),
 request_hash text not null check(request_hash~'^[0-9a-f]{64}$'),
 created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default(clock_timestamp()+interval '15 minutes'),
 foreign key(policy_version_id,product_id)references public.controlled_stock_policy_versions(id,product_id)on delete restrict,
 foreign key(state_head_id,product_id)references public.controlled_stock_state_events(id,product_id)on delete restrict,
 foreign key(opening_id,product_id)references public.controlled_stock_openings(id,product_id)on delete restrict,
 check(expires_at>created_at),unique(id,actor_id,writer)
);
create table public.controlled_stock_cancellations(
 id uuid primary key references public.controlled_stock_preparations(id)on delete restrict,
 actor_id uuid not null references public.profiles(id)on delete restrict,writer text not null,
 session_id uuid not null,recorded_at timestamptz not null default clock_timestamp(),
 foreign key(id,actor_id,writer)references public.controlled_stock_preparations(id,actor_id,writer)on delete restrict
);
create table public.controlled_stock_actions(
 id uuid primary key references public.controlled_stock_preparations(id)on delete restrict,
 actor_id uuid not null references public.profiles(id)on delete restrict,writer text not null,
 session_id uuid not null,request_hash text not null check(request_hash~'^[0-9a-f]{64}$'),
 receipt jsonb not null check(jsonb_typeof(receipt)='object'and octet_length(receipt::text)<=2097152),
 recorded_at timestamptz not null default clock_timestamp(),
 foreign key(id,actor_id,writer)references public.controlled_stock_preparations(id,actor_id,writer)on delete restrict
);
create table public.controlled_stock_events(
 id uuid primary key references public.controlled_stock_actions(id)deferrable initially deferred,
 product_id uuid not null references public.catalog_products(id)on delete restrict,
 sequence bigint not null check(sequence>0),prior_event_id uuid unique,
 policy_version_id uuid not null,opening_id uuid not null,
 engine_revision integer not null references public.controlled_stock_engine_manifests(revision)on delete restrict,
 writer text not null,event_kind text not null,
 actor_id uuid not null references public.profiles(id)on delete restrict,session_id uuid not null,
 actor_name text not null check(length(actor_name)between 1 and 200),
 basis text not null check(basis in('physical_record','correction_assertion','annotation','discrepancy_assertion')),
 observed_at timestamptz check(isfinite(observed_at)),recorded_at timestamptz not null default clock_timestamp(),
 note text not null check(length(note)between 1 and 4000),context_hash text not null check(context_hash~'^[0-9a-f]{64}$'),
 canonical_result jsonb not null check(jsonb_typeof(canonical_result)='object'),
 source_bundle jsonb not null,source_effects jsonb not null,clinical_snapshot jsonb not null,
 secondary_review_required boolean not null,prior_record_hash text,record_hash text not null check(record_hash~'^[0-9a-f]{64}$'),
 foreign key(policy_version_id,product_id)references public.controlled_stock_policy_versions(id,product_id)on delete restrict,
 foreign key(opening_id,product_id)references public.controlled_stock_openings(id,product_id)on delete restrict,
 unique(product_id,sequence),unique(id,product_id),
 foreign key(prior_event_id,product_id)references public.controlled_stock_events(id,product_id)on delete restrict,
 check((sequence=1)=(prior_event_id is null)),check((sequence=1)=(prior_record_hash is null)),
 check((basis='physical_record')=(observed_at is not null))
);
alter table public.controlled_stock_actions add constraint controlled_stock_action_event_fk foreign key(id)references public.controlled_stock_events(id)deferrable initially deferred;
alter table public.controlled_stock_states add constraint controlled_stock_product_event_fk foreign key(last_event_id,product_id)references public.controlled_stock_events(id,product_id)deferrable initially deferred;
create table public.controlled_stock_containers(
 id uuid primary key,product_id uuid not null references public.catalog_products(id)on delete restrict,
 stock_unit text not null check(length(stock_unit)between 1 and 50),label text not null check(length(label)between 1 and 200),
 kind text not null check(kind in('stock','prepared')),stock_lot_id uuid references public.inventory_lots(id)on delete restrict,
 controlling_site_id uuid not null references public.controlled_stock_sites(id)on delete restrict,
 initial_location_id uuid not null,initial_custodian_id uuid references public.profiles(id)on delete restrict,
 opening_id uuid references public.controlled_stock_openings(id)on delete restrict,
 created_event_id uuid references public.controlled_stock_events(id)deferrable initially deferred,
 actor_id uuid not null references public.profiles(id)on delete restrict,session_id uuid not null,
 recorded_at timestamptz not null default clock_timestamp(),
 foreign key(initial_location_id,controlling_site_id)references public.controlled_stock_locations(id,site_id)on delete restrict,
 check((kind='stock')=(stock_lot_id is not null)),check(num_nonnulls(opening_id,created_event_id)=1)
);
create table public.controlled_stock_container_transitions(
 id uuid primary key,event_id uuid not null references public.controlled_stock_events(id)on delete restrict,
 container_id uuid not null references public.controlled_stock_containers(id)on delete restrict,
 version_before bigint not null check(version_before>=0),version_after bigint not null check(version_after=version_before+1),
 before_location_id uuid references public.controlled_stock_locations(id)on delete restrict,
 before_custodian_id uuid references public.profiles(id)on delete restrict,
 before_status text not null check(before_status in('onsite','handed_off','disposed')),
 after_location_id uuid references public.controlled_stock_locations(id)on delete restrict,
 after_custodian_id uuid references public.profiles(id)on delete restrict,
 after_status text not null check(after_status in('onsite','handed_off','disposed')),
 unique(event_id,container_id),unique(container_id,version_after),unique(container_id,version_after,event_id)
);
create table public.controlled_stock_container_heads(
 container_id uuid primary key references public.controlled_stock_containers(id)on delete restrict,
 version bigint not null check(version>=0),location_id uuid references public.controlled_stock_locations(id)on delete restrict,
 custodian_id uuid references public.profiles(id)on delete restrict,
 status text not null check(status in('onsite','handed_off','disposed')),last_event_id uuid,
 check((version=0)=(last_event_id is null)),check((status='onsite')=(location_id is not null)),
 check(status='onsite'or custodian_id is null),
 foreign key(container_id,version,last_event_id)references public.controlled_stock_container_transitions(container_id,version_after,event_id)deferrable initially deferred
);
create table public.controlled_stock_cells(
 id uuid primary key,container_id uuid not null references public.controlled_stock_containers(id)on delete restrict,
 lot_id uuid not null references public.inventory_lots(id)on delete restrict,
 channel text not null check(channel in('available','prepared','return_held')),
 dispense_id uuid references public.native_dispenses(id)on delete restrict,
 allocation_id uuid references public.native_dispense_allocations(id)on delete restrict,
 intake_id uuid references public.native_return_events(id)on delete restrict,
 opening_id uuid references public.controlled_stock_openings(id)on delete restrict,
 created_event_id uuid references public.controlled_stock_events(id)deferrable initially deferred,
 opening_quantity numeric(14,3)not null check(opening_quantity>=0),
 check(num_nonnulls(opening_id,created_event_id)=1),check(created_event_id is null or opening_quantity=0),
 check((channel='available'and dispense_id is null and allocation_id is null and intake_id is null)
  or(channel='prepared'and dispense_id is not null and allocation_id is not null and intake_id is null)
  or(channel='return_held'and dispense_id is not null and allocation_id is not null and intake_id is not null)),
 unique nulls not distinct(container_id,lot_id,channel,dispense_id,allocation_id,intake_id)
);
create table public.controlled_stock_positions(
 cell_id uuid primary key references public.controlled_stock_cells(id)on delete restrict,
 quantity numeric(14,3)not null check(quantity>=0)
);
create table public.controlled_stock_source_links(
 id uuid primary key,event_id uuid not null references public.controlled_stock_events(id)on delete restrict,
 movement_id uuid unique references public.inventory_movements(id)on delete restrict,
 return_event_id uuid unique references public.native_return_events(id)on delete restrict,
 discrepancy_event_id uuid unique references public.native_return_discrepancy_events(id)on delete restrict,
 pickup_id uuid unique references public.native_pickups(id)on delete restrict,
 correction_event_id uuid unique references public.native_dispense_correction_events(id)on delete restrict,
 check(num_nonnulls(movement_id,return_event_id,discrepancy_event_id,pickup_id,correction_event_id)=1)
);
create table public.controlled_stock_event_lines(
 id uuid primary key,event_id uuid not null references public.controlled_stock_events(id)on delete restrict,
 cell_id uuid not null references public.controlled_stock_cells(id)on delete restrict,
 source_link_id uuid not null references public.controlled_stock_source_links(id)on delete restrict,
 quantity_delta numeric(14,3)not null check(quantity_delta<>0),
 container_version_before bigint not null check(container_version_before>=0),
 container_version_after bigint not null check(container_version_after=container_version_before+1),
 unique(event_id,cell_id,source_link_id)
);
create table public.controlled_stock_execution_contexts(
 backend_pid integer primary key,server_started_at timestamptz not null,transaction_id bigint not null,
 transaction_started_at timestamptz not null,statement_started_at timestamptz not null,
 nonce uuid not null,operation_id uuid not null,writer text not null,
 actor_id uuid not null,session_id uuid not null,phase text not null check(phase='executing')
);

-- CONTROLLED_RELEASE_AFTER_SCHEMA --

create function public.controlled_stock_keys(value jsonb,keys text[])returns void
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$begin
 if jsonb_typeof(value)is distinct from 'object'
 or(select count(*)from jsonb_object_keys(value))<>cardinality(keys)
 or exists(select 1 from jsonb_object_keys(value)k where not(k=any(keys)))then
  raise exception 'Exact controlled-operation fields required'using errcode='23514';end if;
end $$;
create function public.controlled_stock_uuid(value jsonb)returns uuid
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$declare result uuid;begin
 if jsonb_typeof(value)is distinct from 'string'then raise exception 'Canonical controlled UUID required'using errcode='23514';end if;
 begin result:=(value#>>'{}')::uuid;exception when invalid_text_representation then
  raise exception 'Canonical controlled UUID required'using errcode='23514';end;
 if result::text is distinct from value#>>'{}'or result='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'Canonical controlled UUID required'using errcode='23514';end if;return result;
end $$;
create function public.controlled_stock_decimal(value jsonb,allow_zero boolean default false)returns numeric
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$declare result numeric;begin
 if jsonb_typeof(value)is distinct from 'string'or value#>>'{}'!~'^-?(0|[1-9][0-9]{0,10})([.][0-9]{1,3})?$'then
  raise exception 'Exact stock decimal string required; maximum three decimal places'using errcode='23514';end if;
 result:=(value#>>'{}')::numeric;
 if not allow_zero and result=0 then raise exception 'Nonzero controlled quantity required'using errcode='23514';end if;
 return result;
end $$;
create function public.controlled_stock_text(value jsonb,maximum integer,multiline boolean default false)returns text
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$declare result text;begin
 if jsonb_typeof(value)is distinct from 'string'then raise exception 'Bounded controlled text required'using errcode='23514';end if;
 result:=value#>>'{}';
 if char_length(result)not between 1 and maximum or result<>btrim(result,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
 or exists(select 1 from regexp_split_to_table(result,'')c where not((multiline and ascii(c)in(9,10))or(ascii(c)>=32 and ascii(c)<>127)))then
  raise exception 'Use clean bounded controlled text'using errcode='23514';end if;return result;
end $$;
create function public.controlled_stock_actor(expected_actor uuid default null)returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$declare actor uuid:=auth.uid();begin
 if current_setting('transaction_isolation')<>'read committed'then
  raise exception 'Controlled stock requires READ COMMITTED isolation'using errcode='23514';end if;
 if auth.jwt()->>'role'is distinct from 'authenticated'or actor is null
 or public.clinical_require_staff()is distinct from actor
 or(expected_actor is not null and actor is distinct from expected_actor)then
  raise exception 'Matched active controlled-record staff required'using errcode='42501';end if;
 -- Called again in a fresh command after every blocking resource/container wait.
 perform public.next_visit_review_session();return actor;
end $$;
create function public.controlled_stock_writer(value text)returns void
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$begin
 if value is null or value not in('receive_inventory','adjust_inventory','record_patient_treatment',
 'record_native_dispense','record_native_dispense_return','record_native_dispense_return_v2',
 'record_anesthesia_drug_administration','record_native_return_discrepancy',
 'record_native_pickup','append_native_dispense_correction')then
  raise exception 'Reviewed controlled producer required'using errcode='23514';end if;
end $$;
create function public.controlled_stock_immutable()returns trigger
language plpgsql set search_path=public,pg_temp set timezone='UTC' as $$begin
 raise exception 'Controlled stock evidence is immutable'using errcode='23514';
end $$;

create function public.controlled_stock_hash(value jsonb)returns text
language sql immutable set search_path=public,pg_temp set timezone='UTC' as $$
 select encode(sha256(convert_to(value::text,'UTF8')),'hex')
$$;
create function public.controlled_stock_identity(p_product uuid)returns jsonb
language sql stable set search_path=public,pg_temp set timezone='UTC' as $$
 select jsonb_build_object('id',id,'name',name,'kind',kind,'manufacturer',manufacturer,'unit',unit)
 from public.catalog_products where id=p_product
$$;
create function public.controlled_stock_gate(p_actor uuid,p_id uuid)returns uuid
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$declare actor uuid;begin
 if p_actor is null or p_id is null or p_id='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'Matched controlled operation actor and UUID required'using errcode='42501';end if;
 actor:=public.controlled_stock_actor(p_actor);
 perform pg_advisory_xact_lock_shared(90271040,0);
 perform public.controlled_stock_actor(actor);
 perform pg_advisory_xact_lock(hashtextextended('controlled-stock-operation:'||p_id::text,0));
 perform public.controlled_stock_actor(actor);
 perform public.controlled_stock_manifest_required();
 return actor;
end $$;
create function public.controlled_stock_product_gate(p_actor uuid,p_product uuid)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$begin
 if p_product is null then raise exception 'Controlled product identity required'using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('controlled-stock-product:'||p_product::text,0));
 perform public.controlled_stock_actor(p_actor);
end $$;
create function public.controlled_stock_exclusive()returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$declare actor uuid:=public.controlled_stock_actor();begin
 if exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'
  and classid=90271040 and objid=0 and objsubid=2 and mode='ShareLock'and granted)then
  raise exception 'Finish the shared stock transaction before exclusive freeze'using errcode='23514';end if;
 perform pg_advisory_xact_lock(90271040,0);
 perform public.controlled_stock_actor(actor);
 if not exists(select 1 from public.user_roles where user_id=actor and role in('DVM','ADMIN'))then
  raise exception 'Current controlled configuration reviewer required'using errcode='42501';end if;
end $$;
create function public.controlled_stock_root_exists(p_id uuid)returns boolean
language sql volatile set search_path=public,pg_temp set timezone='UTC' as $$
 select exists(select 1 from public.inventory_movements where id=p_id)
 or exists(select 1 from public.patient_treatments where id=p_id)
 or exists(select 1 from public.anesthesia_drug_administrations where id=p_id)
 or exists(select 1 from public.native_fulfillment_operations where id=p_id)
 or exists(select 1 from public.native_dispenses where id=p_id)
 or exists(select 1 from public.native_pickups where id=p_id)
 or exists(select 1 from public.native_return_operations where id=p_id)
 or exists(select 1 from public.native_return_events where id=p_id)
 or exists(select 1 from public.native_return_discrepancy_operations where id=p_id)
 or exists(select 1 from public.native_return_discrepancy_events where id=p_id)
 or exists(select 1 from public.native_dispense_correction_operations where id=p_id)
 or exists(select 1 from public.native_dispense_correction_events where id=p_id)
$$;
create function public.controlled_stock_current()returns public.controlled_stock_execution_contexts
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$declare r public.controlled_stock_execution_contexts;begin
 select * into r from public.controlled_stock_execution_contexts where backend_pid=pg_backend_pid()
 and server_started_at=pg_postmaster_start_time()and transaction_id=txid_current()
 and transaction_started_at=transaction_timestamp()and statement_started_at=statement_timestamp()
 and actor_id=auth.uid()and session_id::text=auth.jwt()->>'session_id'and phase='executing';
 return r;
end $$;

create function public.controlled_stock_expected(
 p_id uuid,p_writer text,p_arguments jsonb
)returns jsonb language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare request jsonb:=p_arguments->'request';result jsonb:='[]';a jsonb;lot uuid;did uuid;iid uuid;
 q numeric;action text;prepared integer;held integer;begin
 if p_writer in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration')then
  if p_writer in('receive_inventory','adjust_inventory')then lot:=(p_arguments->>'lot_id')::uuid;q:=public.controlled_stock_decimal(p_arguments->'quantity');
  else lot:=(request->>'lot_id')::uuid;q:=-(request->>'quantity')::numeric;
   if q is null or q>=0 or q<>round(q,3)or q::text in('NaN','Infinity','-Infinity')then
    raise exception 'Exact positive canonical treatment quantity required'using errcode='23514';end if;
  end if;
  result:=jsonb_build_array(jsonb_build_object('lot_id',lot,'channel','available','dispense_id',null,'intake_id',null,'quantity_delta',q::text));
 elsif p_writer='record_native_dispense'then
  for a in select value from jsonb_array_elements(request->'allocations')loop
   lot:=(a->>'lot_id')::uuid;q:=public.native_fulfillment_quantity(a->'quantity');
   result:=result||jsonb_build_array(
    jsonb_build_object('lot_id',lot,'channel','available','dispense_id',null,'intake_id',null,'quantity_delta',(-q)::text),
    jsonb_build_object('lot_id',lot,'channel','prepared','dispense_id',p_id,'intake_id',null,'quantity_delta',q::text));
  end loop;
 elsif p_writer='record_native_pickup'then
  did:=(request->>'dispense_id')::uuid;
  for a in select to_jsonb(v)from public.native_dispense_allocations v where v.dispense_id=did loop
   result:=result||jsonb_build_array(jsonb_build_object('lot_id',a->'lot_id','channel','prepared','dispense_id',did,
    'intake_id',null,'quantity_delta',(-(a->>'quantity')::numeric)::text));
  end loop;
 elsif p_writer in('record_native_dispense_return','record_native_dispense_return_v2')then
  action:=request#>>'{intent,action}';did:=(request#>>'{intent,target,dispense_id}')::uuid;
  iid:=case action when 'intake'then p_id else(request#>>'{intent,intake_id}')::uuid end;
  case action
   when 'intake'then prepared:=-1;held:=1;
   when 'dispose','restock'then prepared:=0;held:=-1;
   when 'retract_intake'then prepared:=1;held:=-1;
   when 'retract_disposal','retract_restock'then prepared:=0;held:=1;
   else raise exception 'Reviewed original return subtype required'using errcode='23514';end case;
  for a in select value from jsonb_array_elements(request#>'{intent,allocations}')loop
   select lot_id into lot from public.native_dispense_allocations where id=(a->>'allocation_id')::uuid and dispense_id=did;
   if lot is null then raise exception 'Original native return allocation required'using errcode='23514';end if;
   q:=public.native_fulfillment_quantity(a->'quantity');
   if action in('restock','retract_restock')then
    result:=result||jsonb_build_array(jsonb_build_object('lot_id',lot,'channel','available','dispense_id',null,'intake_id',null,
     'quantity_delta',(case action when 'restock'then q else -q end)::text));
   end if;
   if prepared<>0 then result:=result||jsonb_build_array(jsonb_build_object('lot_id',lot,'channel','prepared','dispense_id',did,'intake_id',null,'quantity_delta',(prepared*q)::text));end if;
   result:=result||jsonb_build_array(jsonb_build_object('lot_id',lot,'channel','return_held','dispense_id',did,'intake_id',iid,'quantity_delta',(held*q)::text));
  end loop;
 elsif p_writer not in('record_native_return_discrepancy','append_native_dispense_correction')then
  raise exception 'Reviewed controlled source writer required'using errcode='23514';end if;
 if jsonb_array_length(result)>200 then raise exception 'Bounded expected controlled effects required'using errcode='23514';end if;
 return result;
end $$;
create function public.controlled_stock_effect_totals(value jsonb)returns jsonb
language sql immutable set search_path=public,pg_temp set timezone='UTC' as $$
 select coalesce(jsonb_agg(jsonb_build_object('lot_id',lot,'channel',channel,'dispense_id',did,'intake_id',iid,
  'quantity_delta',q)order by lot,channel,did,iid),'[]'::jsonb)
 from(select(v->>'lot_id')::uuid lot,v->>'channel'channel,nullif(v->>'dispense_id','')::uuid did,
  nullif(v->>'intake_id','')::uuid iid,sum((v->>'quantity_delta')::numeric)q
  from jsonb_array_elements(value)v group by 1,2,3,4)grouped
$$;
create function public.controlled_stock_correction_allocations(p_id uuid,p_writer text,p_arguments jsonb,p_context jsonb)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare target uuid;sequence_before bigint;c jsonb;line jsonb;cell uuid;original numeric;already numeric;delta numeric;
begin
 if p_writer<>'record_native_dispense_return_v2'or p_arguments#>>'{request,intent,action}'not like 'retract_%'then return;end if;
 target:=(p_arguments#>>'{request,intent,correction_target,event_id}')::uuid;
 if target is null or not exists(select 1 from public.controlled_stock_events where id=target and product_id=(p_context->>'product_id')::uuid)then
  raise exception 'Pre-opening custody correction requires a separately reviewed exception'using errcode='23514';end if;
 select sequence into sequence_before from public.controlled_stock_events where id=p_id;
 for c in select value from jsonb_array_elements(p_context->'containers')loop
  for line in select value from jsonb_array_elements(c->'lines')loop
   select id into cell from public.controlled_stock_cells where container_id=(c->>'id')::uuid and lot_id=(line->>'lot_id')::uuid
    and channel=line->>'channel'and dispense_id is not distinct from(line->>'dispense_id')::uuid
    and intake_id is not distinct from(line->>'intake_id')::uuid;
   select sum(quantity_delta)into original from public.controlled_stock_event_lines where event_id=target and cell_id=cell;
   delta:=(line->>'quantity_delta')::numeric;
   select coalesce(sum(abs(l.quantity_delta)),0)into already from public.controlled_stock_event_lines l
    join public.controlled_stock_events e on e.id=l.event_id where l.cell_id=cell and e.id<>p_id
    and(e.source_bundle#>>'{native,document,correction_target,event_id}')::uuid=target
    and(sequence_before is null or e.sequence<sequence_before);
   if original is null or(original>0)=(delta>0)or abs(delta)>abs(original)-already then
    raise exception 'Correction must reverse the remaining quantity in its exact original physical cells'using errcode='23514';end if;
  end loop;
 end loop;
end $$;
create function public.controlled_stock_check_plan(p_id uuid,p_writer text,p_arguments jsonb,p_context jsonb)returns jsonb
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$declare expected jsonb;planned jsonb;basis text;begin
 expected:=public.controlled_stock_expected(p_id,p_writer,p_arguments);
 select coalesce(jsonb_agg(line),'[]'::jsonb)into planned from jsonb_array_elements(p_context->'containers')c
 cross join lateral jsonb_array_elements(c->'lines')line;
 if exists(select 1 from jsonb_array_elements(expected)x group by x-'quantity_delta'having count(*)<>1)then
  raise exception 'Every expected source effect must be unambiguous'using errcode='23514';end if;
 if exists(select 1 from jsonb_array_elements(planned)p where
  (select count(*)from jsonb_array_elements(expected)e where e-'quantity_delta'=p-'quantity_delta'
   and((e->>'quantity_delta')::numeric>0)=((p->>'quantity_delta')::numeric>0))<>1)then
  raise exception 'A physical allocation cannot hide a transfer or opposing movement'using errcode='23514';end if;
 if public.controlled_stock_effect_totals(expected)is distinct from public.controlled_stock_effect_totals(planned)then
  raise exception 'Container allocations must match every exact canonical stock and custody effect'using errcode='23514';end if;
 if p_writer='append_native_dispense_correction'then basis:='annotation';
 elsif p_writer='record_native_return_discrepancy'then basis:='discrepancy_assertion';
 elsif p_writer in('record_native_dispense_return','record_native_dispense_return_v2')and p_arguments#>>'{request,intent,action}'like 'retract_%'then basis:='correction_assertion';
 else basis:='physical_record';end if;
 if p_context#>>'{basis,kind}'is distinct from basis then
  raise exception 'Evidence basis must preserve the canonical physical or assertion meaning'using errcode='23514';end if;
 perform public.controlled_stock_correction_allocations(p_id,p_writer,p_arguments,p_context);
 return expected;
end $$;

create function public.controlled_stock_event_kind(p_writer text,p_arguments jsonb)returns text
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$declare subtype text;begin
 perform public.controlled_stock_writer(p_writer);
 if p_writer in('record_native_dispense_return','record_native_dispense_return_v2','record_native_return_discrepancy')then
  subtype:=p_arguments#>>'{request,intent,action}';
 elsif p_writer='append_native_dispense_correction'then subtype:=p_arguments#>>'{request,kind}';
 else return p_writer;end if;
 if subtype is null or length(subtype)>80 then raise exception 'Explicit controlled source subtype required'using errcode='23514';end if;
 return p_writer||':'||subtype;
end $$;
create function public.controlled_stock_arguments(p_writer text,p_arguments jsonb)returns uuid
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare product uuid;request jsonb;did uuid;products uuid[];n numeric;stamp date;begin
 perform public.controlled_stock_writer(p_writer);
 if jsonb_typeof(p_arguments)is distinct from 'object'or octet_length(p_arguments::text)>131072 then
  raise exception 'Bounded original controlled arguments required'using errcode='23514';end if;
 if p_writer='receive_inventory'then
  perform public.controlled_stock_keys(p_arguments,array['lot_id','product_id','lot_number','expires_on','location','quantity','reason']);
  perform public.controlled_stock_uuid(p_arguments->'lot_id');product:=public.controlled_stock_uuid(p_arguments->'product_id');
  perform public.controlled_stock_text(p_arguments->'lot_number',200);perform public.controlled_stock_text(p_arguments->'location',200);
  perform public.controlled_stock_text(p_arguments->'reason',2000,true);n:=public.controlled_stock_decimal(p_arguments->'quantity');
  if n<=0 or jsonb_typeof(p_arguments->'expires_on')is distinct from 'string'or p_arguments->>'expires_on'!~'^\d{4}-\d{2}-\d{2}$'then
   raise exception 'Positive exact receipt and finite lot date required'using errcode='23514';end if;
  stamp:=(p_arguments->>'expires_on')::date;
  if not isfinite(stamp)then raise exception 'Finite lot date required'using errcode='23514';end if;
 elsif p_writer='adjust_inventory'then
  perform public.controlled_stock_keys(p_arguments,array['lot_id','quantity','reason']);
  perform public.controlled_stock_decimal(p_arguments->'quantity');perform public.controlled_stock_text(p_arguments->'reason',2000,true);
  select l.product_id into product from public.inventory_lots l where l.id=public.controlled_stock_uuid(p_arguments->'lot_id');
 else
  if p_writer='record_anesthesia_drug_administration'then
   perform public.controlled_stock_keys(p_arguments,array['record_id','pet_id','request']);
   perform public.controlled_stock_uuid(p_arguments->'record_id');perform public.controlled_stock_uuid(p_arguments->'pet_id');
  else perform public.controlled_stock_keys(p_arguments,array['request']);end if;
  request:=p_arguments->'request';
  if jsonb_typeof(request)is distinct from 'object'or octet_length(request::text)>65536 then
   raise exception 'Bounded unchanged canonical request required'using errcode='23514';end if;
  if p_writer in('record_patient_treatment','record_anesthesia_drug_administration')then
   if request->'historical'='true'::jsonb then raise exception 'Managed treatment must identify actual stock'using errcode='23514';end if;
   select l.product_id into product from public.inventory_lots l where l.id=(request->>'lot_id')::uuid;
  elsif p_writer='record_native_dispense'then
   select(public.native_rx_verified_authorization((request->>'authorization_id')::uuid)#>>'{context,draft,fields,product_id}')::uuid into product;
  else
   if p_writer in('record_native_dispense_return','record_native_dispense_return_v2','record_native_return_discrepancy')then
    did:=(request#>>'{intent,target,dispense_id}')::uuid;
   else did:=(request->>'dispense_id')::uuid;end if;
   select array_agg(distinct l.product_id)into products from public.native_dispense_allocations a
    join public.inventory_lots l on l.id=a.lot_id where a.dispense_id=did;
   if cardinality(products)is distinct from 1 then raise exception 'Single original controlled dispense product required'using errcode='23514';end if;
   product:=products[1];
  end if;
 end if;
 if product is null then raise exception 'Exact original controlled product required'using errcode='23514';end if;
 return product;
end $$;
create function public.controlled_stock_permission(
 p_actor uuid,p_writer text,p_arguments jsonb,p_context jsonb
)returns jsonb language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare policy public.controlled_stock_policy_versions;s public.controlled_stock_state_events;opening public.controlled_stock_openings;
 product uuid;kind text;permission jsonb;role_name jsonb;location_kind jsonb;observed timestamptz;
begin
 perform public.controlled_stock_actor(p_actor);
 product:=public.controlled_stock_uuid(p_context->'product_id');
 select * into policy from public.controlled_stock_policy_versions where id=public.controlled_stock_uuid(p_context->'policy_version_id')and product_id=product;
 select e.*into s from public.controlled_stock_states h join public.controlled_stock_state_events e on e.id=h.head_id
  where h.product_id=product and h.head_id=public.controlled_stock_uuid(p_context->'state_head_id');
 select * into opening from public.controlled_stock_openings where id=public.controlled_stock_uuid(p_context->'opening_id')and product_id=product;
 if policy.id is null or s.id is null or opening.id is null or s.state<>'active'
  or s.policy_version_id<>policy.id or s.opening_id<>opening.id
  or policy.stock_unit is distinct from policy.identity_snapshot->>'unit'
  or policy.stock_unit is distinct from(select stock_unit from public.controlled_stock_policy_versions where id=opening.policy_version_id)
  or policy.engine_revision is distinct from(select max(revision)from public.controlled_stock_engine_manifests)
  or policy.identity_snapshot is distinct from public.controlled_stock_identity(product)then
  raise exception 'Current reviewed controlled policy and opening required'using errcode='PT409';end if;
 kind:=public.controlled_stock_event_kind(p_writer,p_arguments);permission:=policy.permissions->kind;
 perform public.controlled_stock_keys(permission,array['enabled','roles','basis','witness','secondary_review','location_kinds']);
 if permission->'enabled'is distinct from 'true'::jsonb or jsonb_typeof(permission->'roles')is distinct from 'array'
  or jsonb_array_length(permission->'roles')not between 1 and 3
  or permission->>'basis'not in('physical_record','correction_assertion','annotation','discrepancy_assertion')
  or permission->>'basis'is distinct from p_context#>>'{basis,kind}'
  or jsonb_typeof(permission->'witness')is distinct from 'string'or permission->>'witness'not in('none','c2_required')
  or jsonb_typeof(permission->'secondary_review')is distinct from 'boolean'
  or jsonb_typeof(permission->'location_kinds')is distinct from 'array'
  or jsonb_array_length(permission->'location_kinds')not between 1 and 2 then
  raise exception 'Explicit reviewed event permissions required'using errcode='42501';end if;
 for role_name in select value from jsonb_array_elements(permission->'roles')loop
  if jsonb_typeof(role_name)is distinct from 'string'or role_name#>>'{}'not in('DVM','ADMIN','STAFF')then
   raise exception 'Explicit staff permission roles required'using errcode='23514';end if;
 end loop;
 if not exists(select 1 from public.user_roles where user_id=p_actor and role::text in(select value from jsonb_array_elements_text(permission->'roles')))then
  raise exception 'Current staff role cannot perform this controlled event'using errcode='42501';end if;
 for location_kind in select value from jsonb_array_elements(permission->'location_kinds')loop
  if jsonb_typeof(location_kind)is distinct from 'string'or location_kind#>>'{}'not in('clinic','mobile_kit')then
   raise exception 'Explicit physical location kinds required'using errcode='23514';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_context->'containers')c
  left join public.controlled_stock_container_heads h on h.container_id=(c->>'id')::uuid
  cross join lateral(values(h.location_id),((c#>>'{after,location_id}')::uuid),((c#>>'{create,location_id}')::uuid))v(id)
  join public.controlled_stock_locations l on l.id=v.id
  where l.kind not in(select value from jsonb_array_elements_text(permission->'location_kinds')))then
  raise exception 'Reviewed event permission does not cover this actual physical location'using errcode='42501';end if;
 if permission->>'witness'<>'none'then
  raise exception 'Actual physical-witness workflow must be completed before this event is available'using errcode='23514';end if;
 if p_context#>>'{basis,kind}'='physical_record'then
  observed:=public.appointment_catalog_instant(p_context#>'{basis,observed_at}');
  if observed<opening.observed_at or observed>clock_timestamp()then
   raise exception 'Actual observation must follow the opening and cannot be in the future'using errcode='23514';end if;
 elsif p_context#>'{basis,observed_at}'is distinct from 'null'::jsonb then
  raise exception 'Annotations and correction assertions cannot invent a physical observation time'using errcode='23514';
 end if;
 if p_writer in('record_native_dispense_return','record_native_dispense_return_v2')and not policy.clinic_retained_return_permitted then
  raise exception 'Reviewed clinic-retained return permission required'using errcode='23514';end if;
 return permission;
end $$;
create function public.controlled_stock_context(p_writer text,p_id uuid,p_arguments jsonb,p_context jsonb)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare c jsonb;line jsonb;after_value jsonb;created jsonb;container public.controlled_stock_containers;
 cid uuid;previous uuid;lot uuid;did uuid;iid uuid;location uuid;site uuid;channel text;container_kind text;stock_lot uuid;
 keys text[];seen text[];key text;total integer:=0;delta numeric;position numeric;container_total numeric;
begin
 perform public.controlled_stock_keys(p_context,array['version','product_id','policy_version_id','state_head_id','opening_id','basis','containers']);
 if p_context->'version'is distinct from '1'::jsonb or octet_length(p_context::text)>262144 then
  raise exception 'Bounded version-one controlled context required'using errcode='23514';end if;
 perform public.controlled_stock_uuid(p_context->'product_id');perform public.controlled_stock_uuid(p_context->'policy_version_id');
 perform public.controlled_stock_uuid(p_context->'state_head_id');perform public.controlled_stock_uuid(p_context->'opening_id');
 perform public.controlled_stock_keys(p_context->'basis',array['kind','observed_at','note']);
 perform public.controlled_stock_text(p_context#>'{basis,note}',4000,true);
 if p_context#>>'{basis,kind}'is null or p_context#>>'{basis,kind}'not in('physical_record','correction_assertion','annotation','discrepancy_assertion')then
  raise exception 'Explicit controlled evidence basis required'using errcode='23514';end if;
 if jsonb_typeof(p_context->'containers')is distinct from 'array'or jsonb_array_length(p_context->'containers')>32 then
  raise exception 'Bounded explicit physical container context required'using errcode='23514';end if;
 for c in select value from jsonb_array_elements(p_context->'containers')loop
  perform public.controlled_stock_keys(c,array['id','expected_version','create','after','lines']);
  cid:=public.controlled_stock_uuid(c->'id');
  if previous is not null and cid<=previous then raise exception 'Sorted unique controlled container identities required'using errcode='23514';end if;
  previous:=cid;created:=c->'create';after_value:=c->'after';
  perform public.controlled_stock_keys(after_value,array['status','location_id','custodian_id']);
  if after_value->>'status'is null or after_value->>'status'not in('onsite','handed_off','disposed')then
   raise exception 'Explicit physical custody status required'using errcode='23514';end if;
  if after_value->'custodian_id'<>'null'::jsonb then perform public.controlled_stock_uuid(after_value->'custodian_id');end if;
  if after_value->>'status'='onsite'then location:=public.controlled_stock_uuid(after_value->'location_id');
  elsif after_value->'location_id'is distinct from 'null'::jsonb or after_value->'custodian_id'is distinct from 'null'::jsonb then
   raise exception 'Released container cannot remain located or assigned in the clinic'using errcode='23514';
  else location:=null;end if;
  if c->'expected_version'='null'::jsonb then
   perform public.controlled_stock_keys(created,array['kind','label','stock_lot_id','site_id','location_id','custodian_id']);
   container_kind:=created->>'kind';perform public.controlled_stock_text(created->'label',200);
   site:=public.controlled_stock_uuid(created->'site_id');perform public.controlled_stock_uuid(created->'location_id');
   if created->'custodian_id'<>'null'::jsonb then perform public.controlled_stock_uuid(created->'custodian_id');end if;
   if container_kind='stock'then
    stock_lot:=public.controlled_stock_uuid(created->'stock_lot_id');
    if p_writer<>'receive_inventory'or stock_lot<>public.controlled_stock_uuid(p_arguments->'lot_id')then
     raise exception 'Receiving alone creates a new actual stock container'using errcode='23514';end if;
   elsif container_kind='prepared'and p_writer='record_native_dispense'and created->'stock_lot_id'='null'::jsonb then stock_lot:=null;
   else raise exception 'New prepared container requires its actual native dispense'using errcode='23514';end if;
   if after_value->>'status'<>'onsite'or after_value->'location_id'is distinct from created->'location_id'
    or after_value->'custodian_id'is distinct from created->'custodian_id'
    or exists(select 1 from public.controlled_stock_containers where id=cid)then
    raise exception 'New container identity or initial physical context changed'using errcode='PT409';end if;
  else
   if created is distinct from 'null'::jsonb then raise exception 'Existing container cannot be redefined'using errcode='23514';end if;
   perform public.appointment_catalog_integer(c->'expected_version',0,2147483647);
   select * into container from public.controlled_stock_containers where id=cid;
   if container.id is null or container.product_id<>public.controlled_stock_uuid(p_context->'product_id')then
    raise exception 'Current exact product container required'using errcode='23514';end if;
   if not exists(select 1 from public.controlled_stock_container_heads where container_id=cid and version=(c->>'expected_version')::bigint)
    or container.stock_unit is distinct from(select stock_unit from public.controlled_stock_policy_versions where id=(p_context->>'policy_version_id')::uuid)then
    raise exception 'Current exact container head and stock unit required'using errcode='PT409';end if;
   container_kind:=container.kind;stock_lot:=container.stock_lot_id;site:=container.controlling_site_id;
   if p_writer='receive_inventory'then raise exception 'Receiving must identify new actual containers'using errcode='23514';end if;
   perform public.controlled_stock_transition_allowed(p_writer,p_arguments,cid,after_value);
  end if;
  if location is not null and not exists(select 1 from public.controlled_stock_locations where id=location and site_id=site)then
   raise exception 'Physical location must belong to the actual controlling site'using errcode='23514';end if;
  if not exists(select 1 from public.controlled_stock_policy_sites where policy_version_id=public.controlled_stock_uuid(p_context->'policy_version_id')and site_id=site)then
   raise exception 'Reviewed registered-site policy membership required'using errcode='23514';end if;
  if jsonb_typeof(c->'lines')is distinct from 'array'or jsonb_array_length(c->'lines')>100 then
   raise exception 'Bounded container allocation lines required'using errcode='23514';end if;
  seen:='{}';
  for line in select value from jsonb_array_elements(c->'lines')loop
   total:=total+1;
   perform public.controlled_stock_keys(line,array['lot_id','channel','dispense_id','intake_id','quantity_delta']);
   lot:=public.controlled_stock_uuid(line->'lot_id');delta:=public.controlled_stock_decimal(line->'quantity_delta');
   did:=null;iid:=null;channel:=line->>'channel';
   if line->'dispense_id'<>'null'::jsonb then did:=public.controlled_stock_uuid(line->'dispense_id');end if;
   if line->'intake_id'<>'null'::jsonb then iid:=public.controlled_stock_uuid(line->'intake_id');end if;
   if(channel='available'and container_kind='stock'and lot=stock_lot and did is null and iid is null)
    or(channel='prepared'and container_kind='prepared'and did is not null and iid is null)
    or(channel='return_held'and container_kind='prepared'and did is not null and iid is not null)then null;
   else raise exception 'Exact container lot and custody provenance required'using errcode='23514';end if;
   if p_writer='record_native_dispense'and did is not null and did<>p_id then
    raise exception 'Prepared custody belongs to this actual dispense'using errcode='23514';end if;
   if p_writer='record_native_dispense'and container_kind='prepared'and c->'expected_version'<>'null'::jsonb then
    raise exception 'Native preparation must identify new actual patient packages'using errcode='23514';end if;
   if exists(select 1 from public.inventory_lots l where l.id=lot and l.product_id<>public.controlled_stock_uuid(p_context->'product_id'))
    or(not exists(select 1 from public.inventory_lots l where l.id=lot)
     and not(p_writer='receive_inventory'and lot=(p_arguments->>'lot_id')::uuid))then
    raise exception 'Every physical allocation must use its exact product lot'using errcode='23514';end if;
   key:=jsonb_build_array(lot,channel,did,iid)::text;
   if key=any(seen)then raise exception 'Unique container allocation identity required'using errcode='23514';end if;
   seen:=array_append(seen,key);
   if c->'expected_version'='null'::jsonb and delta<=0 then
    raise exception 'A new physical container cannot supply existing quantity'using errcode='23514';end if;
   select coalesce(sum(p.quantity),0)into position from public.controlled_stock_cells cell
    join public.controlled_stock_positions p on p.cell_id=cell.id where cell.container_id=cid and cell.lot_id=lot and cell.channel=line->>'channel'
     and cell.dispense_id is not distinct from did and cell.intake_id is not distinct from iid;
   if position+delta<0 then raise exception 'Reviewed container cannot supply this exact quantity'using errcode='PT409';end if;
  end loop;
  if after_value->>'status'<>'onsite'then
   select coalesce(sum(p.quantity),0)into container_total from public.controlled_stock_cells cell join public.controlled_stock_positions p on p.cell_id=cell.id where cell.container_id=cid;
   select container_total+coalesce(sum((l->>'quantity_delta')::numeric),0)into container_total from jsonb_array_elements(c->'lines')l;
   if container_total<>0 then raise exception 'A released container cannot retain reviewed physical quantity'using errcode='23514';end if;
  end if;
 end loop;
 if p_writer in('record_patient_treatment','record_anesthesia_drug_administration')
  and public.appointment_catalog_instant(p_context#>'{basis,observed_at}')is distinct from public.appointment_catalog_instant(p_arguments#>'{request,administered_at}')then
  raise exception 'Managed administration must preserve its actual original administration time'using errcode='23514';end if;
 if total>200 then raise exception 'Bounded total controlled allocation lines required'using errcode='23514';end if;
end $$;

create function public.controlled_stock_freeze(p_actor uuid,p_id uuid,p_writer text,p_arguments jsonb,p_context jsonb)returns jsonb
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare product uuid:=public.controlled_stock_arguments(p_writer,p_arguments);preview jsonb:='null';
 request jsonb:=p_arguments->'request';containers jsonb;lots jsonb;native_kind text;
begin
 if product is distinct from public.controlled_stock_uuid(p_context->'product_id')then
  raise exception 'Controlled product does not match the original canonical arguments'using errcode='23514';end if;
 perform public.controlled_stock_context(p_writer,p_id,p_arguments,p_context);
 if p_writer='record_native_dispense'then
  preview:=public.preview_native_dispense(request-array['expected_context_hash','reason','attest_alert_review','attest_dispense_review']);
 elsif p_writer='record_native_pickup'then preview:=public.preview_native_pickup((request->>'dispense_id')::uuid,(request->>'pet_id')::uuid,request->'refill_close');
 elsif p_writer='append_native_dispense_correction'then preview:=public.preview_native_dispense_correction((request->>'authorization_id')::uuid,(request->>'pet_id')::uuid,(request->>'dispense_id')::uuid);
 elsif p_writer='record_native_dispense_return'then preview:=public.preview_native_dispense_return(request->'intent');
 elsif p_writer='record_native_dispense_return_v2'then preview:=public.preview_native_dispense_return_v2(request->'intent');
 elsif p_writer='record_native_return_discrepancy'then preview:=public.preview_native_return_discrepancy(request->'intent');end if;
 perform public.controlled_stock_actor(p_actor);
 if preview<>'null'::jsonb and(preview->>'context_hash'is distinct from request->>'expected_context_hash'
  or(preview?'allowed'and preview->'allowed'is distinct from 'true'::jsonb))then
  raise exception 'Original canonical review is stale or unavailable'using errcode='PT409';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.value->'id','container',to_jsonb(t),'head',to_jsonb(h),
  'cells',(select coalesce(jsonb_agg(jsonb_build_object('cell',to_jsonb(cell),'position',to_jsonb(pos))order by cell.id),'[]'::jsonb)
   from public.controlled_stock_cells cell join public.controlled_stock_positions pos on pos.cell_id=cell.id where cell.container_id=t.id)
 )order by c.value->>'id'),'[]'::jsonb)into containers from jsonb_array_elements(p_context->'containers')c
 left join public.controlled_stock_containers t on t.id=(c.value->>'id')::uuid
 left join public.controlled_stock_container_heads h on h.container_id=t.id;
 if exists(select 1 from jsonb_array_elements(containers)c where octet_length(c::text)>131072)then
  raise exception 'Bounded exact container snapshot required'using errcode='23514';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',ids.id,'lot',to_jsonb(l),
  'available',(select coalesce(sum(m.quantity),0)::text from public.inventory_movements m where m.lot_id=ids.id),
  'native_hold',public.native_reconciliation_lot_held(ids.id))order by ids.id),'[]'::jsonb)into lots
 from(select distinct(line->>'lot_id')::uuid id from jsonb_array_elements(p_context->'containers')c
  cross join lateral jsonb_array_elements(c->'lines')line)ids left join public.inventory_lots l on l.id=ids.id;
 return jsonb_build_object('catalog',(select to_jsonb(p)from public.catalog_products p where p.id=product),
  'containers',containers,'lots',lots,'native',preview->'context');
end $$;

-- Local source-reconciliation oracle for C1b engineering proofs only.
-- Installed in pg_temp inside a rolled-back owned clone; never a hosted RPC.
create or replace function public.controlled_stock_source_bundle(
 p_writer text,p_root uuid,p_actor uuid,p_result jsonb
)returns jsonb language plpgsql volatile security invoker
set search_path=public,pg_temp set timezone='UTC' as $$
declare expected jsonb;native_document jsonb;native_kind text;dispense uuid;
 product uuid;products uuid[];available jsonb;allocations jsonb;
 movement_count integer;actual_actor uuid;source_count integer;return_source jsonb;verified_dispense jsonb;
begin
 if p_root is null or p_actor is null or p_result is null then
  raise exception 'Exact controlled source identity required'using errcode='23514';end if;
 case p_writer
 when 'receive_inventory','adjust_inventory'then
  select to_jsonb(m),m.created_by into expected,actual_actor
  from public.inventory_movements m where m.id=p_root;
 when 'record_patient_treatment'then
  select to_jsonb(t),t.created_by into expected,actual_actor
  from public.patient_treatments t where t.id=p_root and not t.historical;
 when 'record_anesthesia_drug_administration'then
  -- The outer writer returns its treatment row, not the separate audit link.
  select to_jsonb(t),a.created_by into expected,actual_actor
  from public.anesthesia_drug_administrations a
  join public.patient_treatments t on t.id=a.id and t.created_by=a.created_by
  where a.id=p_root;
 when 'record_native_dispense'then
  select public.native_fulfillment_receipt(o),d.actor_id,d.id,d.document
  into expected,actual_actor,dispense,native_document
  from public.native_dispenses d join public.native_fulfillment_operations o
   on o.id=d.id and o.operation='dispense'and o.actor_id=d.actor_id
  where d.id=p_root and o.result->'dispense'=d.document;
  native_kind:='dispense';
 when 'record_native_dispense_return','record_native_dispense_return_v2'then
  select e.actor_id,e.dispense_id,e.document into actual_actor,dispense,native_document
  from public.native_return_events e join public.stock_custody_sources s
   on s.event_id=e.id and s.actor_id=e.actor_id and s.writer=p_writer
  join public.native_return_operations o on o.id=e.id and o.actor_id=e.actor_id and o.result=e.document
  where e.id=p_root and e.document->>'version'=case p_writer when 'record_native_dispense_return'then '1'else '2'end;
  if p_writer='record_native_dispense_return'then
   select public.native_return_receipt(o)into expected from public.native_return_operations o where o.id=p_root;
  else
   select jsonb_build_object('version',2,'id',o.id,'actor_id',o.actor_id,'request',o.request,
    'request_hash',o.request_hash,'result',o.result,'created_at',o.created_at)into expected
   from public.native_return_operations o where o.id=p_root;
  end if;
  -- Provenance remains verifiable after the original recorder retires. This
  -- private data reader must not borrow an owner-only recovery RPC's Auth gate.
  perform public.native_reconciliation_verified((native_document#>>'{target,authorization_id}')::uuid,
   (native_document#>>'{target,pet_id}')::uuid,dispense);
  native_kind:='return';
  select jsonb_build_object('action',e.action,'intake_id',coalesce(e.intake_id,e.id),
   'intake_document',i.document,'intake_reviewed_context',i.reviewed_context)
  into return_source from public.native_return_events e
  join public.native_return_events i on i.id=coalesce(e.intake_id,e.id)
   and i.action='intake'and i.dispense_id=e.dispense_id
  where e.id=p_root;
  if return_source is null then raise exception 'Exact original intake source required'using errcode='23514';end if;
 when 'record_native_return_discrepancy'then
  select e.actor_id,e.dispense_id,e.document into actual_actor,dispense,native_document
  from public.native_return_discrepancy_events e join public.stock_discrepancy_sources s
   on s.event_id=e.id and s.actor_id=e.actor_id
  join public.native_return_discrepancy_operations o on o.id=e.id and o.actor_id=e.actor_id and o.result=e.document
  where e.id=p_root;
  select jsonb_build_object('version',1,'id',o.id,'actor_id',o.actor_id,'request',o.request,
   'request_hash',o.request_hash,'result',o.result,'created_at',o.created_at)into expected
  from public.native_return_discrepancy_operations o where o.id=p_root;
  perform public.native_reconciliation_verified((native_document#>>'{target,authorization_id}')::uuid,
   (native_document#>>'{target,pet_id}')::uuid,dispense);
  native_kind:='discrepancy';
 when 'record_native_pickup'then
  select public.native_fulfillment_receipt(o),e.actor_id,e.dispense_id,e.document
  into expected,actual_actor,dispense,native_document
  from public.native_pickups e join public.stock_pickup_sources s on s.event_id=e.id and s.actor_id=e.actor_id
  join public.native_fulfillment_operations o on o.id=e.id and o.operation='pickup'and o.actor_id=e.actor_id and o.result=e.document
  where e.id=p_root;
  native_kind:='pickup';
 when 'append_native_dispense_correction'then
  select public.native_correction_receipt(o),e.actor_id,e.dispense_id,e.document
  into expected,actual_actor,dispense,native_document
  from public.native_dispense_correction_events e join public.stock_correction_sources s on s.event_id=e.id and s.actor_id=e.actor_id
  join public.native_dispense_correction_operations o on o.id=e.id and o.actor_id=e.actor_id and o.result=e.document
  where e.id=p_root;
  native_kind:='correction';
 else raise exception 'Reviewed controlled source writer required'using errcode='23514';
 end case;
 if expected is null or expected is distinct from p_result or actual_actor is distinct from p_actor then
  raise exception 'Original controlled canonical receipt required'using errcode='23514';end if;

 -- Keep every actual signed movement as a distinct source; never net opposing
 -- compensation entries or assign meaning by the order of generated UUIDs.
 select count(*)::integer into source_count from(select 1 from public.stock_movement_sources s
  where s.writer=p_writer and s.source_id=p_root limit 101)bounded;
 if source_count>100 then raise exception 'Bounded controlled source movements required'using errcode='23514';end if;
 if exists(select 1 from public.stock_movement_sources s where s.writer=p_writer and s.source_id=p_root and s.actor_id is distinct from p_actor)then
  raise exception 'Exact controlled source actor required'using errcode='23514';end if;
 perform public.stock_source_validate_movement(s.movement_id)
 from public.stock_movement_sources s where s.writer=p_writer and s.source_id=p_root;
 select count(*)::integer,array_agg(distinct l.product_id),coalesce(jsonb_agg(jsonb_build_object(
  'kind','movement','id',m.id,'lot_id',m.lot_id,'product_id',l.product_id,
  'quantity_delta',m.quantity::text,'native_kind',m.kind
 )order by m.id),'[]'::jsonb)into movement_count,products,available
 from public.stock_movement_sources s join public.inventory_movements m on m.id=s.movement_id
 join public.inventory_lots l on l.id=m.lot_id
 where s.writer=p_writer and s.source_id=p_root and s.actor_id=p_actor;
 if p_writer in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration')then
  if movement_count<>1 then raise exception 'One original controlled stock movement required'using errcode='23514';end if;
 elsif p_writer in('record_native_return_discrepancy','record_native_pickup','append_native_dispense_correction')and movement_count<>0 then
  raise exception 'Custody or annotation cannot invent available stock effects'using errcode='23514';
 end if;

 if native_kind is not null then
  if native_document is null or dispense is null then raise exception 'Exact native controlled source required'using errcode='23514';end if;
  verified_dispense:=public.native_fulfillment_verified_dispense(dispense);
  if verified_dispense is null or(native_kind='dispense'and verified_dispense is distinct from native_document)then
   raise exception 'Verified original native dispense required'using errcode='23514';end if;
  select array_agg(distinct l.product_id),count(*)::integer,coalesce(jsonb_agg(jsonb_build_object(
   'allocation_id',a.id,'dispense_id',a.dispense_id,'lot_id',a.lot_id,
   'movement_id',a.movement_id,'quantity',a.quantity::text
  )order by a.lot_id),'[]'::jsonb)into products,source_count,allocations
  from public.native_dispense_allocations a join public.inventory_lots l on l.id=a.lot_id
  where a.dispense_id=dispense;
  if source_count not between 1 and 100 or cardinality(products)<>1 then
   raise exception 'Exact single-product native allocation membership required'using errcode='23514';end if;
  if p_writer='record_native_dispense'and movement_count<>source_count then
   raise exception 'Every controlled dispense allocation needs its original debit'using errcode='23514';end if;
 end if;
 if cardinality(products)is distinct from 1 then
  raise exception 'One exact controlled source product required'using errcode='23514';end if;
 product:=products[1];
 if exists(select 1 from jsonb_array_elements(available)source where(source->>'product_id')::uuid is distinct from product)then
  raise exception 'Controlled source product membership changed'using errcode='23514';end if;
 -- The caller must still reconcile per-source custody effects to its frozen
 -- container slots. Returning this bundle never authorizes or posts an event.
 return jsonb_build_object('version',1,'writer',p_writer,'root',p_root,
  'actor_id',p_actor,'product_id',product,'available',available,
  'native',case when native_kind is null then 'null'::jsonb else
   jsonb_build_object('kind',native_kind,'id',p_root,'dispense_id',dispense,
    'document',native_document,'original_allocations',allocations,
    'return_source',coalesce(return_source,'null'::jsonb))end);
end $$;
revoke all on function public.controlled_stock_source_bundle(text,uuid,uuid,jsonb)from public,anon,authenticated,service_role;

-- Read-only reference obligations, not posting or permission to handle a drug.
-- Future engine posting must independently reconcile these to reviewed heads,
-- actual containers, approved policy and a live owned execution context.
create function public.controlled_stock_source_effects(
 p_writer text,p_root uuid,p_actor uuid,p_result jsonb
)returns jsonb language plpgsql volatile security invoker
set search_path=public,pg_temp set timezone='UTC' as $$
declare b jsonb:=public.controlled_stock_source_bundle(p_writer,p_root,p_actor,p_result);
 n jsonb:=b->'native';a jsonb;original jsonb;available jsonb:=b->'available';
 custody jsonb:='[]';kind text:=n->>'kind';action text;delta numeric;
 lot uuid;allocation uuid;movement uuid;intake uuid;dispense uuid;quantity numeric;
 prepared_factor integer;held_factor integer;basis text:='stock_record';requirements jsonb:='{}';
begin
 if n<>'null'::jsonb then dispense:=(n->>'dispense_id')::uuid;end if;
 if kind in('dispense','pickup')then
  basis:=case kind when 'dispense'then 'preparation_record'else 'handoff_record'end;
  requirements:=case kind when 'pickup'then
   '{"complete_original_prepared_package":true,"expected_container_heads_required":true}'::jsonb
   else '{"exact_available_container_allocations_required":true}'::jsonb end;
  for a in select value from jsonb_array_elements(n->'original_allocations')loop
   quantity:=(a->>'quantity')::numeric;allocation:=(a->>'allocation_id')::uuid;lot:=(a->>'lot_id')::uuid;
   if quantity<=0 then raise exception 'Positive original custody allocation required'using errcode='23514';end if;
   if kind='dispense'then
    if(select count(*)from jsonb_array_elements(available)m where m->>'id'=a->>'movement_id'
     and m->>'lot_id'=lot::text and(m->>'quantity_delta')::numeric=-quantity)<>1 then
     raise exception 'Exact original available debit required'using errcode='23514';end if;
   end if;
   custody:=custody||jsonb_build_array(jsonb_build_object('source_kind',kind,'source_id',p_root,
    'allocation_id',allocation,'lot_id',lot,'dispense_id',dispense,'intake_id',null,
    'channel','prepared','quantity_delta',(case kind when 'dispense'then quantity else -quantity end)::text));
  end loop;
 elsif kind='return'then
  action:=n#>>'{return_source,action}';intake:=(n#>>'{return_source,intake_id}')::uuid;
  if action is distinct from n#>>'{document,action}'or intake is null then
   raise exception 'Exact return action and intake identity required'using errcode='23514';end if;
  basis:=case when action like 'retract_%'then 'correction_assertion'else 'custody_record'end;
  -- These are explicit eligibility requirements, not an authorization result.
  -- A recorded-in-error pickup amendment never proves clinic-retained custody.
  requirements:=jsonb_build_object('original_intake_id',intake,
   'original_intake_custody',n#>'{return_source,intake_document,custody}',
   'clinic_retained_before_handoff_required',true,
   'actual_original_pickup_must_be_checked',true,'expected_container_heads_required',true,
   'explicit_restock_destination_required',action in('restock','retract_restock'));
  case action
   when 'intake'then prepared_factor:=-1;held_factor:=1;
   when 'dispose'then prepared_factor:=0;held_factor:=-1;
   when 'restock'then prepared_factor:=0;held_factor:=-1;
   when 'retract_intake'then prepared_factor:=1;held_factor:=-1;
   when 'retract_disposal'then prepared_factor:=0;held_factor:=1;
   when 'retract_restock'then prepared_factor:=0;held_factor:=1;
   else raise exception 'Reviewed return source action required'using errcode='23514';
  end case;
  if jsonb_array_length(n#>'{document,allocations}')not between 1 and 100 then
   raise exception 'Bounded exact return allocation membership required'using errcode='23514';end if;
  if(select count(*)<>count(distinct value->>'allocation_id')from jsonb_array_elements(n#>'{document,allocations}'))then
   raise exception 'Unique return source allocation required'using errcode='23514';end if;
  for a in select value from jsonb_array_elements(n#>'{document,allocations}')loop
   allocation:=(a->>'allocation_id')::uuid;lot:=(a->>'lot_id')::uuid;quantity:=(a->>'quantity')::numeric;
   select value into original from jsonb_array_elements(n->'original_allocations')
    where value->>'allocation_id'=allocation::text and value->>'lot_id'=lot::text;
   if original is null or quantity<=0 or quantity>(original->>'quantity')::numeric then
    raise exception 'Exact positive original return allocation required'using errcode='23514';end if;
   if action in('restock','retract_restock')then
    movement:=(a->>'movement_id')::uuid;delta:=case action when 'restock'then quantity else -quantity end;
    if movement is null or(select count(*)from jsonb_array_elements(available)m where
     m->>'id'=movement::text and m->>'lot_id'=lot::text and(m->>'quantity_delta')::numeric=delta)<>1 then
     raise exception 'Exact signed available return movement required'using errcode='23514';end if;
   elsif a->'movement_id'is distinct from 'null'::jsonb then
    raise exception 'Custody-only source cannot invent available stock'using errcode='23514';
   end if;
   if prepared_factor<>0 then
    custody:=custody||jsonb_build_array(jsonb_build_object('source_kind','return','source_id',p_root,
     'allocation_id',allocation,'lot_id',lot,'dispense_id',dispense,'intake_id',null,
     'channel','prepared','quantity_delta',(quantity*prepared_factor)::text));
   end if;
   custody:=custody||jsonb_build_array(jsonb_build_object('source_kind','return','source_id',p_root,
    'allocation_id',allocation,'lot_id',lot,'dispense_id',dispense,'intake_id',intake,
    'channel','return_held','quantity_delta',(quantity*held_factor)::text));
  end loop;
  if jsonb_array_length(available)<>(case when action in('restock','retract_restock')then
   jsonb_array_length(n#>'{document,allocations}')else 0 end)then
   raise exception 'Every available return movement must have one exact allocation'using errcode='23514';end if;
 elsif kind='discrepancy'then
  basis:='discrepancy_assertion';
  requirements:='{"native_and_controlled_holds_must_compose":true}'::jsonb;
 elsif kind='correction'then
  basis:='annotation';
  requirements:='{"annotation_cannot_restore_stock_or_prove_physical_return":true}'::jsonb;
 end if;
 return jsonb_build_object('version',1,'writer',p_writer,'root',p_root,'actor_id',p_actor,
  'product_id',b->'product_id','basis',basis,'available',available,'custody',custody,
  'requirements',requirements,'authorizes_execution',false);
end $$;
revoke all on function public.controlled_stock_source_effects(text,uuid,uuid,jsonb)from public,anon,authenticated,service_role;

create function public.controlled_stock_container_snapshot(p_context jsonb)returns jsonb
language sql volatile set search_path=public,pg_temp set timezone='UTC' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',c.value->'id','container',to_jsonb(t),'head',to_jsonb(h),
  'cells',(select coalesce(jsonb_agg(jsonb_build_object('cell',to_jsonb(cell),'position',to_jsonb(pos))order by cell.id),'[]'::jsonb)
   from public.controlled_stock_cells cell join public.controlled_stock_positions pos on pos.cell_id=cell.id where cell.container_id=t.id)
 )order by c.value->>'id'),'[]'::jsonb)from jsonb_array_elements(p_context->'containers')c
 left join public.controlled_stock_containers t on t.id=(c.value->>'id')::uuid
 left join public.controlled_stock_container_heads h on h.container_id=t.id
$$;
create function public.controlled_stock_source_totals(p_effects jsonb)returns jsonb
language sql immutable set search_path=public,pg_temp set timezone='UTC' as $$
 select public.controlled_stock_effect_totals(coalesce((select jsonb_agg(jsonb_build_object('lot_id',v->'lot_id',
  'channel','available','dispense_id',null,'intake_id',null,'quantity_delta',v->'quantity_delta'))from jsonb_array_elements(p_effects->'available')v),'[]'::jsonb)
  ||coalesce(p_effects->'custody','[]'::jsonb))
$$;
create function public.controlled_stock_transition_allowed(p_writer text,p_arguments jsonb,p_container uuid,p_after jsonb)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare h public.controlled_stock_container_heads;c public.controlled_stock_containers;action text;begin
 select * into c from public.controlled_stock_containers where id=p_container;
 select * into h from public.controlled_stock_container_heads where container_id=p_container;
 if not found then return;end if;
 action:=p_arguments#>>'{request,intent,action}';
 if p_writer='record_native_pickup'then
  if c.kind<>'prepared'or p_after is distinct from jsonb_build_object('status','handed_off','location_id',null,'custodian_id',null)then
   raise exception 'Complete pickup must release its actual prepared containers'using errcode='23514';end if;
 elsif p_writer in('record_native_dispense_return','record_native_dispense_return_v2')and action='dispose'and c.kind='prepared'
  and p_after->>'status'='disposed'and p_after->'location_id'='null'::jsonb and p_after->'custodian_id'='null'::jsonb then null;
 elsif p_writer='record_native_dispense_return_v2'and action='retract_disposal'and h.status='disposed'
  and c.kind='prepared'and p_after->>'status'='onsite'then null;
 elsif p_after is distinct from jsonb_build_object('status',h.status,'location_id',h.location_id,'custodian_id',h.custodian_id)then
  raise exception 'This source cannot imply a physical transfer or change of custodian'using errcode='23514';end if;
end $$;
create function public.controlled_stock_return_requirements(p_writer text,p_bundle jsonb,p_context jsonb)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare native jsonb:=p_bundle->'native';did uuid;action text;target uuid;c jsonb;lot uuid;prepared numeric;held numeric;begin
 if native='null'::jsonb then return;end if;did:=(native->>'dispense_id')::uuid;
 if native->>'kind'='pickup'then
  if exists(select 1 from public.native_return_events where dispense_id=did)then
   raise exception 'Prior custody history requires a separately reviewed complete-package exception'using errcode='23514';end if;
  if exists(select 1 from public.controlled_stock_cells cell join public.controlled_stock_positions pos on pos.cell_id=cell.id
   where cell.dispense_id=did and cell.channel='return_held'and pos.quantity<>0)then
   raise exception 'Held medication cannot be handed off as the complete prepared package'using errcode='23514';end if;
  for c in select value from jsonb_array_elements(native->'original_allocations')loop
   select coalesce(sum(pos.quantity),0)into prepared from public.controlled_stock_cells cell join public.controlled_stock_positions pos on pos.cell_id=cell.id
    where cell.channel='prepared'and cell.allocation_id=(c->>'allocation_id')::uuid and cell.dispense_id=did;
   if prepared is distinct from(c->>'quantity')::numeric then raise exception 'Pickup requires every exact original prepared allocation'using errcode='23514';end if;
  end loop;
 elsif native->>'kind'='return'then
  if native#>>'{return_source,intake_document,custody}'is distinct from 'clinic_retained'
   or exists(select 1 from public.native_pickups where dispense_id=did)then
   raise exception 'Routine client-returned, unknown or handed-off controlled custody is unavailable'using errcode='23514';end if;
  action:=native#>>'{document,action}';
  if action like 'retract_%'then
   target:=(native#>>'{document,correction_target,event_id}')::uuid;
   if target is null or not exists(select 1 from public.controlled_stock_events e where e.id=target and e.product_id=(p_bundle->>'product_id')::uuid
    and e.source_bundle#>>'{native,kind}'='return')then
    raise exception 'Pre-opening or unlinked custody corrections require a reviewed exception workflow'using errcode='23514';end if;
  end if;
  if action in('intake','retract_intake')then
   for c in select value from jsonb_array_elements(p_context->'containers')loop
    for lot in select distinct(line->>'lot_id')::uuid from jsonb_array_elements(c->'lines')line loop
     select coalesce(sum((line->>'quantity_delta')::numeric)filter(where line->>'channel'='prepared'),0),
      coalesce(sum((line->>'quantity_delta')::numeric)filter(where line->>'channel'='return_held'),0)
     into prepared,held from jsonb_array_elements(c->'lines')line where(line->>'lot_id')::uuid=lot;
     if prepared<>-held then raise exception 'Intake classification must preserve each actual container quantity'using errcode='23514';end if;
    end loop;
   end loop;
  end if;
 end if;
end $$;
create function public.controlled_stock_finish(p_id uuid,p_result jsonb)returns jsonb
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare context public.controlled_stock_execution_contexts:=public.controlled_stock_current();r public.controlled_stock_preparations;
 admission public.stock_writer_admissions:=public.stock_writer_current();policy public.controlled_stock_policy_versions;
 product_head public.controlled_stock_states;event public.controlled_stock_events;container public.controlled_stock_containers;
 head public.controlled_stock_container_heads;bundle jsonb;effects jsonb;permission jsonb;value jsonb;line jsonb;created jsonb;after_value jsonb;
 canonical_catalog jsonb;receipt jsonb;available_link uuid;native_link uuid;cell uuid;allocation uuid;lot uuid;did uuid;iid uuid;
 cid uuid;source uuid;delta numeric;position numeric;before_version bigint;after_version bigint;stamp timestamptz:=clock_timestamp();
begin
 if context.operation_id is distinct from p_id or admission.source_id is distinct from p_id
  or context.writer is distinct from admission.writer or context.actor_id is distinct from admission.actor_id then
  raise exception 'Exact outer owned source admission required to finish controlled posting'using errcode='23514';end if;
 select * into r from public.controlled_stock_preparations where id=p_id and actor_id=context.actor_id and writer=context.writer;
 if not found then raise exception 'Original owned controlled preparation required'using errcode='23514';end if;
 perform public.controlled_stock_actor(r.actor_id);
 bundle:=public.controlled_stock_source_bundle(r.writer,r.id,r.actor_id,p_result);
 effects:=public.controlled_stock_source_effects(r.writer,r.id,r.actor_id,p_result);
 if public.controlled_stock_source_totals(effects)is distinct from public.controlled_stock_effect_totals(r.frozen->'expected_effects')then
  raise exception 'Actual canonical sources do not match the reviewed physical effects'using errcode='23514';end if;
 if exists(select 1 from jsonb_array_elements(effects->'available')a group by a->>'lot_id'having count(*)<>1)then
  raise exception 'Available source slots must be unambiguous; never net movements'using errcode='23514';end if;
 -- Canonical resource locks are already held. This product SHARE tail fixes
 -- the reviewed catalog until commit before acquiring sorted container gates.
 select to_jsonb(p)into canonical_catalog from public.catalog_products p where p.id=r.product_id for share;
 perform public.controlled_stock_actor(r.actor_id);
 if canonical_catalog is distinct from r.frozen->'catalog'then raise exception 'Reviewed controlled catalog changed'using errcode='PT409';end if;
 for value in select v from jsonb_array_elements(r.context->'containers')v order by v->>'id'loop
  perform pg_advisory_xact_lock(hashtextextended('controlled-stock-container:'||(value->>'id'),0));
  perform public.controlled_stock_actor(r.actor_id);
 end loop;
 permission:=public.controlled_stock_permission(r.actor_id,r.writer,r.canonical_arguments,r.context);
 perform public.controlled_stock_manifest_required();perform public.controlled_stock_actor(r.actor_id);
 if public.controlled_stock_container_snapshot(r.context)is distinct from r.frozen->'containers'then
  raise exception 'Controlled container heads or positions changed after review'using errcode='PT409';end if;
 perform public.controlled_stock_return_requirements(r.writer,bundle,r.context);
 select * into policy from public.controlled_stock_policy_versions where id=r.policy_version_id;
 select * into product_head from public.controlled_stock_states where product_id=r.product_id;
 event.id:=r.id;event.product_id:=r.product_id;event.sequence:=product_head.event_version+1;event.prior_event_id:=product_head.last_event_id;
 event.policy_version_id:=policy.id;event.opening_id:=r.opening_id;event.engine_revision:=policy.engine_revision;
 event.writer:=r.writer;event.event_kind:=public.controlled_stock_event_kind(r.writer,r.canonical_arguments);
 event.actor_id:=r.actor_id;event.session_id:=public.next_visit_review_session();
 select full_name into event.actor_name from public.profiles where id=r.actor_id;
 event.basis:=r.context#>>'{basis,kind}';
 if event.basis='physical_record'then event.observed_at:=public.appointment_catalog_instant(r.context#>'{basis,observed_at}');end if;
 event.recorded_at:=stamp;event.note:=r.context#>>'{basis,note}';event.context_hash:=public.controlled_stock_hash(r.context);
 event.canonical_result:=p_result;event.source_bundle:=bundle;event.source_effects:=effects;
 event.clinical_snapshot:=jsonb_build_object('catalog',canonical_catalog,'original_result',p_result);
 event.secondary_review_required:=(permission->>'secondary_review')::boolean;
 select record_hash into event.prior_record_hash from public.controlled_stock_events where id=event.prior_event_id;
 event.record_hash:=public.controlled_stock_hash(to_jsonb(event)-'record_hash');
 insert into public.controlled_stock_events select(event).*;
 for value in select v from jsonb_array_elements(effects->'available')v loop
  insert into public.controlled_stock_source_links(id,event_id,movement_id)values(gen_random_uuid(),r.id,(value->>'id')::uuid);
 end loop;
 native_link:=gen_random_uuid();
 case bundle#>>'{native,kind}'
  when 'return'then insert into public.controlled_stock_source_links(id,event_id,return_event_id)values(native_link,r.id,r.id);
  when 'pickup'then insert into public.controlled_stock_source_links(id,event_id,pickup_id)values(native_link,r.id,r.id);
  when 'discrepancy'then insert into public.controlled_stock_source_links(id,event_id,discrepancy_event_id)values(native_link,r.id,r.id);
  when 'correction'then insert into public.controlled_stock_source_links(id,event_id,correction_event_id)values(native_link,r.id,r.id);
  else native_link:=null;end case;
 for value in select v from jsonb_array_elements(r.context->'containers')v order by v->>'id'loop
  cid:=(value->>'id')::uuid;created:=value->'create';after_value:=value->'after';
  if value->'expected_version'='null'::jsonb then
   insert into public.controlled_stock_containers(id,product_id,stock_unit,label,kind,stock_lot_id,controlling_site_id,initial_location_id,
    initial_custodian_id,created_event_id,actor_id,session_id)values(cid,r.product_id,policy.stock_unit,created->>'label',created->>'kind',
    (created->>'stock_lot_id')::uuid,(created->>'site_id')::uuid,(created->>'location_id')::uuid,(created->>'custodian_id')::uuid,r.id,r.actor_id,event.session_id)
   returning * into container;
   head.container_id:=cid;head.version:=0;head.location_id:=container.initial_location_id;head.custodian_id:=container.initial_custodian_id;
   head.status:='onsite';head.last_event_id:=null;
  else
   select * into container from public.controlled_stock_containers where id=cid;
   select * into head from public.controlled_stock_container_heads where container_id=cid;
   if head.version is distinct from(value->>'expected_version')::bigint then raise exception 'Reviewed container version changed'using errcode='PT409';end if;
  end if;
  before_version:=head.version;after_version:=before_version+1;
  perform public.controlled_stock_transition_allowed(r.writer,r.canonical_arguments,cid,after_value);
  for line in select v from jsonb_array_elements(value->'lines')v loop
   lot:=(line->>'lot_id')::uuid;did:=(line->>'dispense_id')::uuid;iid:=(line->>'intake_id')::uuid;delta:=(line->>'quantity_delta')::numeric;
   allocation:=null;
   if did is not null then select id into allocation from public.native_dispense_allocations where dispense_id=did and lot_id=lot;
    if allocation is null then raise exception 'Actual original native allocation identity required'using errcode='23514';end if;
   end if;
   select c.id into cell from public.controlled_stock_cells c where c.container_id=cid and c.lot_id=lot and c.channel=line->>'channel'
    and c.dispense_id is not distinct from did and c.allocation_id is not distinct from allocation and c.intake_id is not distinct from iid;
   if not found then
    if delta<0 then raise exception 'An unknown physical cell cannot supply quantity'using errcode='23514';end if;
    cell:=gen_random_uuid();
    insert into public.controlled_stock_cells(id,container_id,lot_id,channel,dispense_id,allocation_id,intake_id,created_event_id,opening_quantity)
     values(cell,cid,lot,line->>'channel',did,allocation,iid,r.id,0);
    insert into public.controlled_stock_positions values(cell,0);
   end if;
   select p.quantity into position from public.controlled_stock_positions p where p.cell_id=cell for update;
   perform public.controlled_stock_actor(r.actor_id);
   if position+delta<0 then raise exception 'Insufficient exact physical container quantity'using errcode='PT409';end if;
   if line->>'channel'='available'then
    select l.id into source from public.controlled_stock_source_links l join public.inventory_movements m on m.id=l.movement_id
     where l.event_id=r.id and m.lot_id=lot;
   elsif bundle#>>'{native,kind}'='dispense'then
    select l.id into source from public.controlled_stock_source_links l join public.native_dispense_allocations a on a.movement_id=l.movement_id
     where l.event_id=r.id and a.id=allocation;
   else source:=native_link;end if;
   if source is null then raise exception 'Exact original source link required for each physical allocation'using errcode='23514';end if;
   insert into public.controlled_stock_event_lines values(gen_random_uuid(),r.id,cell,source,delta,before_version,after_version);
   update public.controlled_stock_positions set quantity=position+delta where cell_id=cell;
  end loop;
  if after_value->>'status'<>'onsite'and exists(select 1 from public.controlled_stock_cells c join public.controlled_stock_positions p on p.cell_id=c.id
   where c.container_id=cid and p.quantity<>0)then raise exception 'Released or disposed container still contains medication'using errcode='23514';end if;
  insert into public.controlled_stock_container_transitions values(gen_random_uuid(),r.id,cid,before_version,after_version,
   head.location_id,head.custodian_id,head.status,(after_value->>'location_id')::uuid,(after_value->>'custodian_id')::uuid,after_value->>'status');
  insert into public.controlled_stock_container_heads values(cid,after_version,(after_value->>'location_id')::uuid,(after_value->>'custodian_id')::uuid,after_value->>'status',r.id)
  on conflict(container_id)do update set version=excluded.version,location_id=excluded.location_id,custodian_id=excluded.custodian_id,status=excluded.status,last_event_id=excluded.last_event_id;
 end loop;
 update public.controlled_stock_states set event_version=event.sequence,last_event_id=event.id where product_id=r.product_id;
 receipt:=jsonb_build_object('version',1,'id',r.id,'writer',r.writer,'actor_id',r.actor_id,'canonical_result',p_result,
  'event',to_jsonb(event),'containers',(select coalesce(jsonb_agg(to_jsonb(h)order by h.container_id),'[]'::jsonb)
   from public.controlled_stock_container_heads h where h.last_event_id=r.id));
 insert into public.controlled_stock_actions(id,actor_id,writer,session_id,request_hash,receipt,recorded_at)
  values(r.id,r.actor_id,r.writer,event.session_id,r.request_hash,receipt,stamp);
 perform public.controlled_stock_validate_event(r.id);
 perform public.controlled_stock_validate_product(r.product_id);
 perform public.controlled_stock_actor(r.actor_id);
 return receipt;
end $$;

-- PRIVATE LOCAL CANDIDATE ONLY. These three original scalar helpers deliberately
-- change from SQL to PL/pgSQL to bound retained SQL-function execution memory.
-- Every expression, argument/return type, IMMUTABLE classification, non-STRICT
-- invocation, SECURITY INVOKER and search_path=public is preserved. The installer
-- must first verify the unchanged trusted original catalog; independent captured
-- SQL oracles verify results and all other pg_proc attributes after installation.
-- CREATE OR REPLACE preserves existing owner/ACL. No UTC override, grants,
-- canonical migration, trusted-reference regeneration or hosted installation.
create or replace function public.native_fulfillment_hash(v jsonb)returns text
language plpgsql immutable security invoker set search_path=public as $$
begin
 return encode(sha256(convert_to(v::text,'UTF8')),'hex');
end$$;
create or replace function public.native_fulfillment_decimal(n numeric)returns text
language plpgsql immutable security invoker set search_path=public as $$
begin
 return to_char(n,'FM999999999999999999999999999999990.000');
end$$;
create or replace function public.native_fulfillment_receipt(r public.native_fulfillment_operations)returns jsonb
language plpgsql immutable security invoker set search_path=public as $$
begin
 return jsonb_build_object('version',1,'id',r.id,'actor_id',r.actor_id,'operation',r.operation,'request',r.request,'request_hash',r.request_hash,'result',r.result,'created_at',r.created_at);
end$$;

-- PRIVATE LOCAL CANDIDATE ONLY. No commissioning API, grants or policy defaults.
-- Limits: 200 product dispenses/boundary entries, 100 allocations per dispense,
-- 1000 events per native history family (including later history), 1 MiB boundary.
-- Pre-C1a native sources without provenance remain unsupported, not inferred old.
create function public.controlled_stock_opening_selector(value jsonb)returns integer
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$
declare n integer;begin
 perform public.controlled_stock_keys(value,array['event_id','version','record_hash']);
 if jsonb_typeof(value->'version')is distinct from 'number'or(value->>'version')!~'^(0|[1-9][0-9]{0,3})$'then
  raise exception 'Bounded canonical opening prefix required'using errcode='23514';end if;
 n:=(value->>'version')::integer;
 if n>1000 then raise exception 'Opening prefix exceeds candidate limit'using errcode='23514';end if;
 if n=0 then
  if value is distinct from jsonb_build_object('event_id',null,'version',0,'record_hash',null)then
   raise exception 'Exact empty opening prefix required'using errcode='23514';end if;
 else
  perform public.controlled_stock_uuid(value->'event_id');
  if jsonb_typeof(value->'record_hash')is distinct from 'string'or(value->>'record_hash')!~'^[0-9a-f]{64}$'then
   raise exception 'Exact opening prefix hash required'using errcode='23514';end if;
 end if;return n;
end $$;
create function public.controlled_stock_opening_head(events jsonb,n integer)returns jsonb
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$begin
 if n is null or n<0 or n>1000 or jsonb_typeof(events)is distinct from 'array'or n>jsonb_array_length(events)then
  raise exception 'Exact opening prefix unavailable'using errcode='23514';end if;
 if n=0 then return jsonb_build_object('event_id',null,'version',0,'record_hash',null);end if;
 if(events->(n-1)->>'sequence')::integer is distinct from n then
  raise exception 'Opening prefix sequence mismatch'using errcode='23514';end if;
 return jsonb_build_object('event_id',events->(n-1)->'id','version',n,'record_hash',events->(n-1)->'record_hash');
end $$;
create function public.controlled_stock_opening_contains_head(events jsonb,head jsonb,n integer)returns boolean
language plpgsql immutable set search_path=public,pg_temp set timezone='UTC' as $$declare v integer;begin
 v:=public.controlled_stock_opening_selector(head);
 return v<=n and head=public.controlled_stock_opening_head(events,v);
end $$;
create function public.controlled_stock_opening_pickup(p_dispense uuid)returns jsonb
language plpgsql stable set search_path=public,pg_temp set timezone='UTC' as $$
declare p public.native_pickups;o public.native_fulfillment_operations;d jsonb;c jsonb;r public.native_refill_events;before_refill jsonb;begin
 select * into p from public.native_pickups where dispense_id=p_dispense;
 if not found then return null;end if;
 d:=public.native_fulfillment_verified_dispense(p_dispense);c:=p.document->'reviewed_context';
 select * into o from public.native_fulfillment_operations where id=p.id;
 perform public.controlled_stock_keys(p.document,array['version','id','authorization_id','pet_id','dispense_id','actor_id','recipient_name','recipient_relationship','reason','reviewed_context','reviewed_context_hash','refill_id','refill_event_id','picked_up_at']);
 perform public.controlled_stock_keys(c,array['version','authorization','dispense','existing_pickup_id','refill']);
 perform public.controlled_stock_keys(o.request,array['authorization_id','pet_id','dispense_id','expected_context_hash','recipient_name','recipient_relationship','reason','attest_handoff','refill_close']);
 if d is null or p.document->'version'is distinct from '1'::jsonb or c->'version'is distinct from '1'::jsonb
  or p.document->>'id'is distinct from p.id::text or p.document->>'authorization_id'is distinct from p.authorization_id::text
  or p.document->>'pet_id'is distinct from p.pet_id::text or p.document->>'dispense_id'is distinct from p.dispense_id::text
  or p.document->>'actor_id'is distinct from p.actor_id::text
  or p.authorization_id::text is distinct from d->>'authorization_id'or p.pet_id::text is distinct from d->>'pet_id'
  or public.native_correction_instant(p.document->'picked_up_at')is distinct from p.picked_up_at
  or not isfinite(o.created_at)or o.created_at<p.picked_up_at
  or o.id is null or o.operation<>'pickup'or o.actor_id<>p.actor_id or o.result is distinct from p.document
  or o.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',o.actor_id,'operation','pickup','request',o.request))
  -- Original pickup requests allow mixed-case UUIDs; preserve their exact hash.
  or public.native_rx_uuid(o.request->'authorization_id')is distinct from p.authorization_id
  or public.native_rx_uuid(o.request->'pet_id')is distinct from p.pet_id
  or public.native_rx_uuid(o.request->'dispense_id')is distinct from p.dispense_id
  or o.request->'attest_handoff'is distinct from 'true'::jsonb
  or p.document->'recipient_name'is distinct from o.request->'recipient_name'
  or p.document->'recipient_relationship'is distinct from o.request->'recipient_relationship'
  or p.document->'reason'is distinct from o.request->'reason'
  or p.document->>'reviewed_context_hash'is distinct from public.native_fulfillment_hash(c)
  or o.request->>'expected_context_hash'is distinct from p.document->>'reviewed_context_hash'
  or c->'dispense'is distinct from d or c->'existing_pickup_id'is distinct from 'null'::jsonb
  or c#>>'{authorization,id}'is distinct from p.authorization_id::text
  or c#>>'{authorization,hash}'is distinct from d->>'authorization_hash'
  or not exists(select 1 from public.stock_pickup_sources s where s.event_id=p.id and s.actor_id=p.actor_id)then
  raise exception 'Verified original pickup row, operation and provenance required'using errcode='23514';end if;
 perform public.native_rx_text(o.request->'recipient_name',200);perform public.native_rx_text(o.request->'recipient_relationship',200);perform public.native_rx_text(o.request->'reason',2000);
 if c->'refill'='null'::jsonb then
  if o.request->'refill_close'is distinct from 'null'::jsonb or p.document->'refill_id'is distinct from 'null'::jsonb
   or p.document->'refill_event_id'is distinct from 'null'::jsonb then
   raise exception 'Original pickup refill absence mismatch'using errcode='23514';end if;
 else
  perform public.controlled_stock_keys(c->'refill',array['refill','head_id']);
  perform public.controlled_stock_keys(o.request->'refill_close',array['id','expected_version','reason']);
  before_refill:=c#>'{refill,refill}';
  select * into r from public.native_refill_events where id=public.native_rx_uuid(p.document->'refill_event_id');
  if r.id is null or r.action<>'pickup'or r.actor_id<>p.actor_id
   or r.refill_id is distinct from public.native_rx_uuid(p.document->'refill_id')
   or r.refill_id is distinct from public.native_rx_uuid(o.request#>'{refill_close,id}')
   or r.refill_id::text is distinct from d->>'refill_id'
   or r.before_snapshot is distinct from before_refill or r.prior_event_id is distinct from public.native_rx_uuid(c#>'{refill,head_id}',true)
   or r.revision<>(before_refill->>'version')::integer+1 or o.request#>'{refill_close,expected_version}'is distinct from before_refill->'version'
   or r.reason is distinct from o.request#>>'{refill_close,reason}'
   or r.after_snapshot is distinct from before_refill||jsonb_build_object('version',r.revision,'state','closed','updated_by',p.actor_id,'updated_at',r.after_snapshot->'updated_at')
   or r.fulfillment_reference is distinct from jsonb_build_object('kind','pickup','id',p.id,'dispense_id',p.dispense_id,'authorization_id',p.authorization_id)
   or not isfinite(r.created_at)or r.created_at<p.picked_up_at or r.created_at>o.created_at then
   raise exception 'Original pickup refill closure evidence mismatch'using errcode='23514';end if;
 end if;
 return jsonb_build_object('id',p.id,'document_hash',public.native_fulfillment_hash(p.document),'operation_hash',public.native_fulfillment_hash(public.native_fulfillment_receipt(o)));
end $$;
create function public.controlled_stock_opening_native_entry_for_product(
 p_product uuid,p_stock_unit text,p_dispense uuid,p_return_version integer,p_correction_version integer,p_discrepancy_version integer,p_pickup_id uuid
)returns jsonb language plpgsql stable set search_path=public,pg_temp set timezone='UTC' as $$
declare d jsonb;stored public.native_dispenses;op public.native_fulfillment_operations;return_history jsonb;corrections jsonb;discrepancies jsonb;
 discrepancy_events jsonb;originals jsonb;quantity_events jsonb;replay jsonb;pickup jsonb;pickup_summary jsonb;allocations jsonb:='[]';held jsonb;
 r_alloc record;r_event record;balance jsonb;prepared numeric;slot jsonb;actual_slot jsonb;actual_refill jsonb;slot_time_field text;actual_instant timestamptz;expected_instant timestamptz;maximum numeric;dispensed numeric;refill_row public.native_refill_events;refill_result jsonb;begin
 if p_product is null or p_dispense is null or p_stock_unit is null or length(p_stock_unit)not between 1 and 50
  or p_return_version is null or p_correction_version is null or p_discrepancy_version is null
  or least(p_return_version,p_correction_version,p_discrepancy_version)<0 or greatest(p_return_version,p_correction_version,p_discrepancy_version)>1000 then
  raise exception 'Bounded exact opening native selectors required'using errcode='23514';end if;
 if(select count(*)from public.native_dispense_allocations where dispense_id=p_dispense)not between 1 and 100
  or(select count(*)from public.native_return_events where dispense_id=p_dispense)>1000
  or(select count(*)from public.native_dispense_correction_events where dispense_id=p_dispense)>1000
  or(select count(*)from public.native_return_discrepancy_events where dispense_id=p_dispense)>1000 then
  raise exception 'Native history exceeds opening candidate limit; no truncation permitted'using errcode='23514';end if;
 select * into stored from public.native_dispenses where id=p_dispense;
 d:=public.native_fulfillment_verified_dispense(p_dispense);
 select * into op from public.native_fulfillment_operations where id=p_dispense;
 perform public.controlled_stock_keys(op.request,array['authorization_id','pet_id','slot_index','expected_slot_version','invoice_id','quantity','allocations','refill','expected_context_hash','reason','attest_alert_review','attest_dispense_review']);
 perform public.controlled_stock_keys(op.result,array['dispense','slot','refill_event']);
 if d is null or stored.id is null or op.id is null or op.operation<>'dispense'or op.actor_id<>stored.actor_id
  or op.result->'dispense'is distinct from d
  or op.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',op.actor_id,'operation','dispense','request',op.request))
  or public.native_rx_uuid(op.request->'authorization_id')is distinct from stored.authorization_id
  or public.native_rx_uuid(op.request->'pet_id')is distinct from stored.pet_id
  or op.request->>'expected_context_hash'is distinct from d->>'reviewed_context_hash'
  or op.request-array['expected_context_hash','reason','attest_alert_review','attest_dispense_review']is distinct from d#>'{reviewed_context,target}'
  or op.request->'reason'is distinct from d->'reason'or op.request->'attest_alert_review'is distinct from 'true'::jsonb or op.request->'attest_dispense_review'is distinct from 'true'::jsonb
  or d->>'authorization_id'is distinct from stored.authorization_id::text or d->>'pet_id'is distinct from stored.pet_id::text
  or d->>'unit'is distinct from p_stock_unit or d#>>'{reviewed_context,product,id}'is distinct from p_product::text
  or exists(select 1 from public.native_dispense_allocations a left join public.inventory_lots l on l.id=a.lot_id where a.dispense_id=p_dispense and l.product_id is distinct from p_product)then
  raise exception 'Exact original opening dispense operation, product and stock unit required'using errcode='23514';end if;
 -- Reconstruct the original result slot, never the mutable current slot.
 maximum:=(d#>>'{reviewed_context,signed_artifact,quantity_per_fill}')::numeric;
 dispensed:=coalesce((d#>>'{reviewed_context,slot,dispensed_quantity}')::numeric,0)+stored.quantity;
 if maximum is null or dispensed>maximum or not isfinite(op.created_at)or op.created_at<stored.dispensed_at
  or public.native_rx_uuid(op.request->'invoice_id')is distinct from stored.invoice_id
  or public.native_fulfillment_quantity(op.request->'quantity')is distinct from stored.quantity
  or op.request->'slot_index'is distinct from d->'slot_index'
  or op.request->'expected_slot_version'is distinct from d->'slot_version_before'
  or(d->>'slot_version_after')::integer<>coalesce((d#>>'{reviewed_context,slot,version}')::integer,0)+1 then
  raise exception 'Original dispense request/slot quantities must match retained evidence'using errcode='23514';end if;
 if d#>'{reviewed_context,slot}'='null'::jsonb then
  slot:=jsonb_build_object('id',stored.slot_id,'authorization_id',stored.authorization_id,'index',d->'slot_index',
   'version',d->'slot_version_after','maximum_quantity',public.native_fulfillment_decimal(maximum),
   'dispensed_quantity',public.native_fulfillment_decimal(dispensed),'remaining_quantity',public.native_fulfillment_decimal(maximum-dispensed),
   'state',case when dispensed=maximum then 'closed'else 'open'end,'closure_kind',case when dispensed=maximum then 'filled'else null end,
   'opened_by',stored.actor_id,'opened_at',stored.dispensed_at,'closed_by',case when dispensed=maximum then stored.actor_id else null end,
   'closed_at',case when dispensed=maximum then stored.dispensed_at else null end,'close_reason',null);
 else
  if d#>>'{reviewed_context,slot,id}'is distinct from stored.slot_id::text then raise exception 'Original dispense slot identity mismatch'using errcode='23514';end if;
  slot:=(d#>'{reviewed_context,slot}')||jsonb_build_object('version',d->'slot_version_after','dispensed_quantity',public.native_fulfillment_decimal(dispensed),
   'remaining_quantity',public.native_fulfillment_decimal(maximum-dispensed),'state',case when dispensed=maximum then 'closed'else 'open'end,
   'closure_kind',case when dispensed=maximum then 'filled'else null end,'closed_by',case when dispensed=maximum then stored.actor_id else null end,
   'closed_at',case when dispensed=maximum then stored.dispensed_at else null end);
 end if;
 refill_result:='null'::jsonb;
 if d->'refill_event_id'<>'null'::jsonb then
  select * into refill_row from public.native_refill_events where id=public.native_rx_uuid(d->'refill_event_id');
  if refill_row.id is null or refill_row.action<>'dispense'or refill_row.actor_id<>stored.actor_id
   or refill_row.refill_id::text is distinct from d->>'refill_id'
   or refill_row.before_snapshot is distinct from d#>'{reviewed_context,refill,refill}'
   or refill_row.fulfillment_reference is distinct from jsonb_build_object('kind','dispense','id',p_dispense,'dispense_id',p_dispense,'authorization_id',stored.authorization_id)then
   raise exception 'Original dispense refill event mismatch'using errcode='23514';end if;
  refill_result:=public.native_refill_event(refill_row);
 elsif d#>'{reviewed_context,refill}'is distinct from 'null'::jsonb then raise exception 'Original dispense refill absence mismatch'using errcode='23514';end if;
 -- Only the two reconstructed slot instants may use equivalent offset spelling.
 -- The saved operation/result is never normalized or rewritten; its full original
 -- receipt hash below still witnesses every stored JSON value, including these.
 actual_slot:=op.result->'slot';
 if jsonb_typeof(actual_slot)is distinct from 'object'
  or not(actual_slot?&array['opened_at','closed_at'])
  or actual_slot-array['opened_at','closed_at']is distinct from slot-array['opened_at','closed_at']
  or op.result-array['slot','refill_event']is distinct from jsonb_build_object('dispense',d)then
  raise exception 'Original dispense result must retain its exact slot and refill frame'using errcode='23514';end if;
 foreach slot_time_field in array array['opened_at','closed_at']loop
  if slot_time_field='closed_at'and slot->slot_time_field='null'::jsonb then
   if actual_slot->slot_time_field is distinct from 'null'::jsonb then
    raise exception 'Original dispense slot timestamps must retain exact finite instants'using errcode='23514';end if;
  else
   begin
    expected_instant:=public.native_correction_instant(slot->slot_time_field);
    actual_instant:=public.native_correction_instant(actual_slot->slot_time_field);
   exception when data_exception or check_violation then
    raise exception 'Original dispense slot timestamps must retain exact finite instants'using errcode='23514';
   end;
   if actual_instant is distinct from expected_instant then
    raise exception 'Original dispense slot timestamps must retain exact finite instants'using errcode='23514';end if;
  end if;
 end loop;
 -- The verified original refill event has one reconstructed typed timestamp.
 -- Nested snapshots and every other event field remain exact saved JSON.
 actual_refill:=op.result->'refill_event';
 if refill_result='null'::jsonb then
  if actual_refill is distinct from 'null'::jsonb then
   raise exception 'Original dispense result must retain its exact slot and refill frame'using errcode='23514';end if;
 else
  if refill_row.id is null or jsonb_typeof(actual_refill)is distinct from 'object'or not(actual_refill?'created_at')
   or actual_refill-'created_at'is distinct from refill_result-'created_at'then
   raise exception 'Original dispense result must retain its exact slot and refill frame'using errcode='23514';end if;
  begin
   actual_instant:=public.native_correction_instant(actual_refill->'created_at');
  exception when data_exception or check_violation then
   raise exception 'Original dispense refill timestamp must retain its exact finite instant'using errcode='23514';
  end;
  if not isfinite(refill_row.created_at)or actual_instant is distinct from refill_row.created_at then
   raise exception 'Original dispense refill timestamp must retain its exact finite instant'using errcode='23514';end if;
 end if;
 for r_alloc in select * from public.native_dispense_allocations where dispense_id=p_dispense loop
  perform public.stock_source_validate_movement(r_alloc.movement_id);
 end loop;
 corrections:=public.native_correction_verified(stored.authorization_id,stored.pet_id,p_dispense);
 return_history:=public.native_reconciliation_verified(stored.authorization_id,stored.pet_id,p_dispense);
 perform public.controlled_stock_opening_head(return_history->'events',p_return_version);
 perform public.controlled_stock_opening_head(corrections->'events',p_correction_version);
 discrepancies:=public.native_reconciliation_discrepancies(p_dispense,p_discrepancy_version);
 if(discrepancies->>'open_case_count')::integer<>0 then
  raise exception 'Unresolved cutover discrepancy requires an unavailable exception workflow'using errcode='23514';end if;
 select coalesce(jsonb_agg(document order by sequence),'[]')into discrepancy_events from public.native_return_discrepancy_events where dispense_id=p_dispense;
 pickup:=public.controlled_stock_opening_pickup(p_dispense);
 if p_pickup_id is not null and(pickup is null or pickup->>'id'is distinct from p_pickup_id::text)then
  raise exception 'Actual original opening pickup required'using errcode='23514';end if;
 if p_pickup_id is not null and p_return_version<>0 then
  raise exception 'Handed-off return history requires an unavailable opening exception'using errcode='23514';end if;
 pickup_summary:=case when p_pickup_id is null then null else public.native_correction_pickup(p_dispense)end;
 -- Independent prefix heads must also form one causally closed cutover.
 for r_event in select * from public.native_return_events where dispense_id=p_dispense and sequence<=p_return_version loop
  if not public.controlled_stock_opening_contains_head(corrections->'events',r_event.reviewed_context->'correction_head',p_correction_version)
   or(r_event.document->'version'='2'::jsonb and not public.controlled_stock_opening_contains_head(discrepancy_events,r_event.reviewed_context->'discrepancy_head',p_discrepancy_version))
   or(r_event.reviewed_context->'original_pickup'<>'null'::jsonb and r_event.reviewed_context->'original_pickup'is distinct from coalesce(pickup_summary,'null'::jsonb))then
   raise exception 'Return prefix depends on evidence outside the opening boundary'using errcode='23514';end if;
  if r_event.action='intake'and r_event.document->>'custody'is distinct from 'clinic_retained'then
   raise exception 'Client or unknown opening custody is unavailable'using errcode='23514';end if;
 end loop;
 for r_event in select * from public.native_dispense_correction_events where dispense_id=p_dispense and sequence<=p_correction_version loop
  if(r_event.reviewed_context->'original_pickup'<>'null'::jsonb and r_event.reviewed_context->'original_pickup'is distinct from coalesce(pickup_summary,'null'::jsonb))
   or(r_event.kind='pickup_amendment'and p_pickup_id is null)
   or(r_event.document->>'amends_event_id'is not null and not exists(select 1 from public.native_dispense_correction_events prior
    where prior.id=(r_event.document->>'amends_event_id')::uuid and prior.dispense_id=p_dispense and prior.sequence<r_event.sequence and prior.sequence<=p_correction_version))then
   raise exception 'Correction prefix depends on evidence outside the opening boundary'using errcode='23514';end if;
 end loop;
 for r_event in select * from public.native_return_discrepancy_events where dispense_id=p_dispense and sequence<=p_discrepancy_version loop
  if not public.controlled_stock_opening_contains_head(return_history->'events',r_event.document->'return_head',p_return_version)
   or not exists(select 1 from public.native_return_events src where src.id=(r_event.document#>>'{source,event_id}')::uuid
    and src.dispense_id=p_dispense and src.sequence<=p_return_version and src.record_hash=r_event.document#>>'{source,record_hash}')
   or exists(select 1 from jsonb_array_elements_text(r_event.document->'correction_ids')cid where not exists(
    select 1 from public.native_return_events cr where cr.id=cid::uuid and cr.dispense_id=p_dispense and cr.sequence<=p_return_version))then
   raise exception 'Discrepancy prefix depends on evidence outside the opening boundary'using errcode='23514';end if;
 end loop;
 select jsonb_agg(jsonb_build_object('allocation_id',id,'lot_id',lot_id,'quantity',public.native_fulfillment_decimal(quantity))order by id)into originals from public.native_dispense_allocations where dispense_id=p_dispense;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'sequence',sequence,'action',action,'intake_id',intake_id,
  'correction_target_id',document#>'{correction_target,event_id}','allocations',(select jsonb_agg(x-'movement_id'order by x->>'allocation_id')from jsonb_array_elements(document->'allocations')x))order by sequence),'[]')
 into quantity_events from public.native_return_events where dispense_id=p_dispense and sequence<=p_return_version;
 replay:=public.native_reconciliation_quantity_prefixes(originals,quantity_events)->p_return_version;
 for r_alloc in select * from public.native_dispense_allocations where dispense_id=p_dispense order by id loop
  select x into balance from jsonb_array_elements(replay->'allocations')x where x->>'allocation_id'=r_alloc.id::text;
  prepared:=case when p_pickup_id is not null then 0 else r_alloc.quantity-(balance->>'returned_quantity')::numeric end;
  if prepared is null or prepared<0 then raise exception 'Reconstructible nonnegative opening prepared quantity required'using errcode='23514';end if;
  select coalesce(jsonb_agg(jsonb_build_object('intake_id',x->'id','quantity',y->'held_quantity')order by x->>'id'),'[]')into held
   from jsonb_array_elements(replay->'intakes')x cross join lateral jsonb_array_elements(x->'allocations')y where y->>'allocation_id'=r_alloc.id::text;
  allocations:=allocations||jsonb_build_array(jsonb_build_object('allocation_id',r_alloc.id,'lot_id',r_alloc.lot_id,
   'dispensed_quantity',public.native_fulfillment_decimal(r_alloc.quantity),'prepared_quantity',public.native_fulfillment_decimal(prepared),'held',held));
 end loop;
 return jsonb_build_object('version',1,'dispense_id',p_dispense,'dispense_document_hash',public.native_fulfillment_hash(d),'dispense_operation_hash',public.native_fulfillment_hash(public.native_fulfillment_receipt(op)),
  'return_head',public.controlled_stock_opening_head(return_history->'events',p_return_version),
  'correction_head',public.controlled_stock_opening_head(corrections->'events',p_correction_version),
  'discrepancy_head',discrepancies->'head','pickup',case when p_pickup_id is null then null else pickup end,'allocations',allocations);
end $$;
create function public.controlled_stock_opening_native_entry(
 p_opening uuid,p_dispense uuid,p_return_version integer,p_correction_version integer,p_discrepancy_version integer,p_pickup_id uuid
)returns jsonb language plpgsql stable set search_path=public,pg_temp set timezone='UTC' as $$declare o public.controlled_stock_openings;unit text;begin
 select * into o from public.controlled_stock_openings where id=p_opening;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=o.policy_version_id and product_id=o.product_id;
 if o.id is null or unit is null then raise exception 'Actual opening product and policy required'using errcode='23514';end if;
 return public.controlled_stock_opening_native_entry_for_product(o.product_id,unit,p_dispense,p_return_version,p_correction_version,p_discrepancy_version,p_pickup_id);
end $$;
create function public.controlled_stock_opening_later_source(p_opening uuid,p_kind text,p_source uuid)returns uuid
language plpgsql stable set search_path=public,pg_temp set timezone='UTC' as $$declare e public.controlled_stock_events;o public.controlled_stock_openings;begin
 select * into o from public.controlled_stock_openings where id=p_opening;
 select event.* into e from public.controlled_stock_source_links link join public.controlled_stock_events event on event.id=link.event_id
  where case p_kind when 'movement'then link.movement_id when 'return'then link.return_event_id when 'correction'then link.correction_event_id
   when 'discrepancy'then link.discrepancy_event_id when 'pickup'then link.pickup_id else null end=p_source;
 if e.id is null or e.opening_id is distinct from p_opening or e.product_id is distinct from o.product_id
  or(p_kind<>'movement'and(e.id<>p_source or e.source_bundle#>>'{native,kind}'is distinct from p_kind
   or e.source_bundle#>>'{native,id}'is distinct from p_source::text
   or(p_kind='return'and e.writer not in('record_native_dispense_return','record_native_dispense_return_v2'))
   or(p_kind='correction'and e.writer<>'append_native_dispense_correction')
   or(p_kind='discrepancy'and e.writer<>'record_native_return_discrepancy')
   or(p_kind='pickup'and e.writer<>'record_native_pickup')))then
  raise exception 'Every later source requires its exact owned opening/product event link'using errcode='23514';end if;
 return e.id;
end $$;
create function public.controlled_stock_validate_opening(p_opening uuid)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare o public.controlled_stock_openings;unit text;entry jsonb;projected jsonb;expected jsonb:='[]';by_dispense jsonb:='{}';
 r_dispense record;r_source record;r_movement record;r_cell record;value jsonb;v_held jsonb;entry_id uuid;last_id text:='';rv integer;cv integer;dv integer;pid uuid;event_id uuid;
 old_count bigint;total_count bigint;actual numeric;opening_net numeric;begin
 select * into o from public.controlled_stock_openings where id=p_opening;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=o.policy_version_id and product_id=o.product_id;
 if o.id is null or unit is null or jsonb_typeof(o.native_custody_boundary)is distinct from 'array'
  or jsonb_array_length(o.native_custody_boundary)>200 or octet_length(o.native_custody_boundary::text)>1048576 then
  raise exception 'Bounded actual opening boundary required'using errcode='23514';end if;
 if(select count(distinct a.dispense_id)from public.native_dispense_allocations a join public.inventory_lots l on l.id=a.lot_id where l.product_id=o.product_id)>200 then
  raise exception 'Product native history exceeds opening candidate limit; no truncation permitted'using errcode='23514';end if;
 if exists(select 1 from public.controlled_stock_opening_movements b left join public.inventory_movements m on m.id=b.movement_id
  left join public.inventory_lots l on l.id=m.lot_id where b.opening_id=o.id and(m.id is null or l.product_id is distinct from o.product_id
   or b.lot_id<>m.lot_id or b.quantity<>m.quantity or b.source_snapshot is distinct from to_jsonb(m)))then
  raise exception 'Exact original opening movement snapshots required'using errcode='23514';end if;
 for r_movement in select m.* from public.inventory_movements m join public.inventory_lots l on l.id=m.lot_id where l.product_id=o.product_id loop
  if exists(select 1 from public.controlled_stock_opening_movements b where b.opening_id=o.id and b.movement_id=r_movement.id)then
   if exists(select 1 from public.controlled_stock_source_links where movement_id=r_movement.id)then raise exception 'Opening and managed movement membership overlap'using errcode='23514';end if;
  else
   event_id:=public.controlled_stock_opening_later_source(o.id,'movement',r_movement.id);
  end if;
 end loop;
 if exists(select 1 from public.controlled_stock_containers t where t.opening_id=o.id and(t.product_id<>o.product_id or t.stock_unit<>unit))
  or exists(select 1 from public.controlled_stock_cells cell left join public.controlled_stock_containers t on t.id=cell.container_id
   left join public.inventory_lots l on l.id=cell.lot_id where cell.opening_id=o.id and(t.opening_id is distinct from o.id or t.product_id is distinct from o.product_id
    or l.product_id is distinct from o.product_id or t.stock_unit is distinct from unit or cell.created_event_id is not null
    or(t.kind='stock'and(cell.channel<>'available'or t.stock_lot_id<>cell.lot_id))or(t.kind='prepared'and cell.channel='available')))then
  raise exception 'Exact opening container/cell product, unit and provenance required'using errcode='23514';end if;
 for r_dispense in select id from public.inventory_lots where product_id=o.product_id loop
  select coalesce(sum(quantity),0)into opening_net from public.controlled_stock_opening_movements where opening_id=o.id and lot_id=r_dispense.id;
  select coalesce(sum(opening_quantity),0)into actual from public.controlled_stock_cells where opening_id=o.id and lot_id=r_dispense.id and channel='available';
  if opening_net<>actual or opening_net<0 then raise exception 'Opening available cells must match original opening movement net exactly'using errcode='23514';end if;
 end loop;
 for entry in select x from jsonb_array_elements(o.native_custody_boundary)x loop
  perform public.controlled_stock_keys(entry,array['version','dispense_id','dispense_document_hash','dispense_operation_hash','return_head','correction_head','discrepancy_head','pickup','allocations']);
  if jsonb_typeof(entry->'version')is distinct from 'number'or entry->>'version'<>'1'then raise exception 'Exact opening boundary version required'using errcode='23514';end if;
  entry_id:=public.controlled_stock_uuid(entry->'dispense_id');
  if entry_id::text collate "C"<=last_id collate "C"then raise exception 'Sorted unique opening dispenses required'using errcode='23514';end if;last_id:=entry_id::text;
  rv:=public.controlled_stock_opening_selector(entry->'return_head');cv:=public.controlled_stock_opening_selector(entry->'correction_head');dv:=public.controlled_stock_opening_selector(entry->'discrepancy_head');pid:=null;
  if entry->'pickup'<>'null'::jsonb then perform public.controlled_stock_keys(entry->'pickup',array['id','document_hash','operation_hash']);pid:=public.controlled_stock_uuid(entry#>'{pickup,id}');end if;
  projected:=public.controlled_stock_opening_native_entry(o.id,entry_id,rv,cv,dv,pid);
  if entry is distinct from projected then raise exception 'Stored opening custody must equal the canonical retained native prefix'using errcode='23514';end if;
  expected:=expected||jsonb_build_array(projected);by_dispense:=by_dispense||jsonb_build_object(entry_id::text,projected);
 end loop;
 for r_dispense in select d.id from public.native_dispenses d where exists(select 1 from public.native_dispense_allocations a join public.inventory_lots l on l.id=a.lot_id where a.dispense_id=d.id and l.product_id=o.product_id)loop
  select count(*),count(*)filter(where exists(select 1 from public.controlled_stock_opening_movements b where b.opening_id=o.id and b.movement_id=x.movement_id))
   into total_count,old_count from public.native_dispense_allocations x where x.dispense_id=r_dispense.id;
  if old_count not in(0,total_count)then raise exception 'Native dispense cannot straddle the opening boundary'using errcode='23514';end if;
  entry:=by_dispense->r_dispense.id::text;
  if(old_count>0)is distinct from(entry is not null)then raise exception 'Every original opening dispense requires exactly one boundary entry'using errcode='23514';end if;
  if entry is null then
   -- Verify complete later history too, without adopting its quantities into opening.
   perform public.controlled_stock_opening_native_entry_for_product(o.product_id,unit,r_dispense.id,0,0,0,null);
   for r_movement in select movement_id from public.native_dispense_allocations where dispense_id=r_dispense.id loop
    event_id:=public.controlled_stock_opening_later_source(o.id,'movement',r_movement.movement_id);
    if event_id<>r_dispense.id or not exists(select 1 from public.controlled_stock_events where id=event_id and writer='record_native_dispense')then
     raise exception 'Later dispense requires every exact native debit link'using errcode='23514';end if;
   end loop;
   rv:=0;cv:=0;dv:=0;pid:=null;
  else rv:=(entry#>>'{return_head,version}')::integer;cv:=(entry#>>'{correction_head,version}')::integer;dv:=(entry#>>'{discrepancy_head,version}')::integer;pid:=(entry#>>'{pickup,id}')::uuid;end if;
  for r_source in select 'return'kind,id,sequence,document from public.native_return_events where dispense_id=r_dispense.id
   union all select 'correction',id,sequence,document from public.native_dispense_correction_events where dispense_id=r_dispense.id
   union all select 'discrepancy',id,sequence,document from public.native_return_discrepancy_events where dispense_id=r_dispense.id
   union all select 'pickup',id,1,document from public.native_pickups where dispense_id=r_dispense.id loop
   if(r_source.kind='return'and r_source.sequence<=rv)or(r_source.kind='correction'and r_source.sequence<=cv)or(r_source.kind='discrepancy'and r_source.sequence<=dv)or(r_source.kind='pickup'and r_source.id=pid)then
    if exists(select 1 from public.controlled_stock_source_links k where coalesce(k.return_event_id,k.correction_event_id,k.discrepancy_event_id,k.pickup_id)=r_source.id)then
     raise exception 'Retained prefix and managed native source membership overlap'using errcode='23514';end if;
   else event_id:=public.controlled_stock_opening_later_source(o.id,r_source.kind,r_source.id);end if;
   if r_source.kind='return'then
    for r_movement in select movement_id from public.native_return_stock_links link where link.event_id=r_source.id union all select movement_id from public.native_return_compensation_links link where link.event_id=r_source.id loop
     perform public.stock_source_validate_movement(r_movement.movement_id);
     if r_source.sequence<=rv then
      if not exists(select 1 from public.controlled_stock_opening_movements where opening_id=o.id and movement_id=r_movement.movement_id)then raise exception 'Retained return movement must belong to the same opening prefix'using errcode='23514';end if;
     elsif public.controlled_stock_opening_later_source(o.id,'movement',r_movement.movement_id)<>r_source.id then raise exception 'Later return movement must belong to its exact native event'using errcode='23514';end if;
    end loop;
   end if;
  end loop;
 end loop;
 -- No forged boundary dispense can be absent from the actual old allocation set.
 if exists(select 1 from jsonb_array_elements(expected)e where not exists(select 1 from public.native_dispense_allocations a
  join public.controlled_stock_opening_movements m on m.movement_id=a.movement_id and m.opening_id=o.id where a.dispense_id=(e->>'dispense_id')::uuid))then
  raise exception 'Opening custody cannot invent an old native dispense'using errcode='23514';end if;
 for entry in select x from jsonb_array_elements(expected)x loop
  for value in select x from jsonb_array_elements(entry->'allocations')x loop
   select coalesce(sum(opening_quantity),0)into actual from public.controlled_stock_cells where opening_id=o.id and channel='prepared'
    and dispense_id=(entry->>'dispense_id')::uuid and allocation_id=(value->>'allocation_id')::uuid and lot_id=(value->>'lot_id')::uuid;
   if actual<>(value->>'prepared_quantity')::numeric then raise exception 'Opening prepared custody must reconcile in both directions'using errcode='23514';end if;
   for v_held in select x from jsonb_array_elements(value->'held')x loop
    select coalesce(sum(opening_quantity),0)into actual from public.controlled_stock_cells where opening_id=o.id and channel='return_held'
     and dispense_id=(entry->>'dispense_id')::uuid and allocation_id=(value->>'allocation_id')::uuid and lot_id=(value->>'lot_id')::uuid and intake_id=(v_held->>'intake_id')::uuid;
    if actual<>(v_held->>'quantity')::numeric then raise exception 'Opening held custody must match the exact original intake'using errcode='23514';end if;
   end loop;
  end loop;
 end loop;
 for r_cell in select * from public.controlled_stock_cells where opening_id=o.id and channel<>'available'loop
  entry:=by_dispense->r_cell.dispense_id::text;
  select x into value from jsonb_array_elements(coalesce(entry->'allocations','[]'))x where x->>'allocation_id'=r_cell.allocation_id::text and x->>'lot_id'=r_cell.lot_id::text;
  if entry is null or value is null or(r_cell.channel='return_held'and not exists(select 1 from jsonb_array_elements(value->'held')held_source where held_source->>'intake_id'=r_cell.intake_id::text))then
   raise exception 'Every opening custody cell needs its exact retained native source, including zero cells'using errcode='23514';end if;
 end loop;
 -- Deferred guards validate each new/root event; restore audits every historical
 -- event explicitly. Do not repeat that full audit for every product-row trigger.
end $$;

create function public.controlled_stock_validate_event(p_id uuid)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare e public.controlled_stock_events;a public.controlled_stock_actions;r public.controlled_stock_preparations;
 b jsonb;effects jsonb;value jsonb;heads jsonb;frozen_container jsonb;actual numeric;expected numeric;v record;source uuid;expected_links integer;
begin
 select * into e from public.controlled_stock_events where id=p_id;
 select * into a from public.controlled_stock_actions where id=p_id;
 select * into r from public.controlled_stock_preparations where id=p_id;
 if e.id is null or a.id is null or r.id is null or e.actor_id<>r.actor_id or a.actor_id<>r.actor_id
  or e.writer<>r.writer or a.writer<>r.writer or a.request_hash<>r.request_hash
  or e.product_id<>r.product_id or e.policy_version_id<>r.policy_version_id or e.opening_id<>r.opening_id
  or e.session_id<>a.session_id or e.recorded_at<>a.recorded_at or e.recorded_at<r.created_at
  or e.event_kind is distinct from public.controlled_stock_event_kind(r.writer,r.canonical_arguments)
  or e.basis is distinct from r.context#>>'{basis,kind}'or e.note is distinct from r.context#>>'{basis,note}'
  or e.observed_at is distinct from(case when e.basis='physical_record'then public.appointment_catalog_instant(r.context#>'{basis,observed_at}')else null end)
  or(e.observed_at is not null and(e.observed_at>e.recorded_at or e.observed_at<(select observed_at from public.controlled_stock_openings where id=e.opening_id)))
  or e.engine_revision is distinct from(select engine_revision from public.controlled_stock_policy_versions where id=e.policy_version_id)
  or e.secondary_review_required is distinct from(r.frozen#>>'{permission,secondary_review}')::boolean
  or e.clinical_snapshot is distinct from jsonb_build_object('catalog',r.frozen->'catalog','original_result',e.canonical_result)
  or e.context_hash<>public.controlled_stock_hash(r.context)
  or e.record_hash<>public.controlled_stock_hash(to_jsonb(e)-'record_hash')
  or exists(select 1 from public.controlled_stock_cancellations where id=p_id)then
  raise exception 'Exact immutable owned controlled event/action evidence required'using errcode='23514';end if;
 if e.sequence>1 and not exists(select 1 from public.controlled_stock_events prior where prior.id=e.prior_event_id
  and prior.product_id=e.product_id and prior.sequence=e.sequence-1 and prior.record_hash=e.prior_record_hash)then
  raise exception 'Controlled product event predecessor mismatch'using errcode='23514';end if;
 b:=public.controlled_stock_source_bundle(e.writer,e.id,e.actor_id,e.canonical_result);
 effects:=public.controlled_stock_source_effects(e.writer,e.id,e.actor_id,e.canonical_result);
 if e.source_bundle is distinct from b or e.source_effects is distinct from effects
  or public.controlled_stock_source_totals(effects)is distinct from public.controlled_stock_effect_totals(r.frozen->'expected_effects')then
  raise exception 'Controlled event must preserve every exact original canonical source'using errcode='23514';end if;
 expected_links:=jsonb_array_length(effects->'available')+case when b#>>'{native,kind}'in('return','pickup','discrepancy','correction')then 1 else 0 end;
 if(select count(*)from public.controlled_stock_source_links where event_id=e.id)<>expected_links then
  raise exception 'Exact controlled source-link membership required'using errcode='23514';end if;
 if b#>>'{native,kind}'in('return','pickup','discrepancy','correction')and not exists(
  select 1 from public.controlled_stock_source_links k where k.event_id=e.id and
   case b#>>'{native,kind}'when 'return'then k.return_event_id=e.id when 'pickup'then k.pickup_id=e.id
    when 'discrepancy'then k.discrepancy_event_id=e.id when 'correction'then k.correction_event_id=e.id else false end)then
  raise exception 'Exact original native source family and root required'using errcode='23514';end if;
 for value in select element.value from jsonb_array_elements(effects->'available')element(value)loop
  source:=null;
  select id into source from public.controlled_stock_source_links where event_id=e.id and movement_id=(value->>'id')::uuid;
  if source is null then raise exception 'Available stock movement missing its exact controlled source link'using errcode='23514';end if;
  select coalesce(sum(l.quantity_delta),0)into actual from public.controlled_stock_event_lines l
   join public.controlled_stock_cells c on c.id=l.cell_id
   where l.event_id=e.id and l.source_link_id=source and c.channel='available'and c.lot_id=(value->>'lot_id')::uuid;
  if actual is distinct from(value->>'quantity_delta')::numeric then
   raise exception 'Controlled available allocations must total their actual signed movement'using errcode='23514';end if;
 end loop;
 for value in select element.value from jsonb_array_elements(effects->'custody')element(value)loop
  select coalesce(sum(l.quantity_delta),0)into actual from public.controlled_stock_event_lines l
   join public.controlled_stock_cells c on c.id=l.cell_id join public.controlled_stock_source_links s on s.id=l.source_link_id
   where l.event_id=e.id and c.channel=value->>'channel'and c.lot_id=(value->>'lot_id')::uuid
    and c.allocation_id=(value->>'allocation_id')::uuid and c.dispense_id=(value->>'dispense_id')::uuid
    and c.intake_id is not distinct from(value->>'intake_id')::uuid
    and(case when b#>>'{native,kind}'='dispense'then s.movement_id=(select movement_id from public.native_dispense_allocations where id=c.allocation_id)
     else coalesce(s.return_event_id,s.pickup_id)=e.id end);
  if actual is distinct from(value->>'quantity_delta')::numeric then
   raise exception 'Controlled custody allocation must preserve its exact native source'using errcode='23514';end if;
 end loop;
 for v in select l.*,c.channel,c.lot_id,c.dispense_id,c.allocation_id,c.intake_id,c.container_id,s.event_id as source_event_id,
  s.movement_id,s.return_event_id,s.pickup_id,s.discrepancy_event_id,s.correction_event_id,t.product_id
  from public.controlled_stock_event_lines l join public.controlled_stock_cells c on c.id=l.cell_id
  join public.controlled_stock_source_links s on s.id=l.source_link_id
  join public.controlled_stock_containers t on t.id=c.container_id where l.event_id=e.id loop
  if v.source_event_id<>e.id or v.product_id<>e.product_id
   or not exists(select 1 from public.controlled_stock_container_transitions t where t.event_id=e.id and t.container_id=v.container_id
    and t.version_before=v.container_version_before and t.version_after=v.container_version_after)then
   raise exception 'Controlled line source, product and container transition must agree'using errcode='23514';end if;
  if v.channel='available'then
   if not exists(select 1 from jsonb_array_elements(effects->'available')x where(x->>'id')::uuid=v.movement_id
    and(x->>'lot_id')::uuid=v.lot_id and((x->>'quantity_delta')::numeric>0)=(v.quantity_delta>0))then
    raise exception 'Available line cannot borrow another source or hide an opposing movement'using errcode='23514';end if;
  else
   if not exists(select 1 from jsonb_array_elements(effects->'custody')x where x->>'channel'=v.channel
    and(x->>'lot_id')::uuid=v.lot_id and(x->>'allocation_id')::uuid=v.allocation_id
    and(x->>'dispense_id')::uuid=v.dispense_id and(x->>'intake_id')::uuid is not distinct from v.intake_id
    and((x->>'quantity_delta')::numeric>0)=(v.quantity_delta>0))then
    raise exception 'Custody line cannot borrow another native allocation or source meaning'using errcode='23514';end if;
  end if;
 end loop;
 if(select count(*)from public.controlled_stock_container_transitions where event_id=e.id)<>jsonb_array_length(r.context->'containers')then
  raise exception 'Every reviewed container must have one exact immutable transition'using errcode='23514';end if;
 for value in select element.value from jsonb_array_elements(r.context->'containers')element(value)loop
  select x.item into frozen_container from jsonb_array_elements(r.frozen->'containers')x(item)where x.item->>'id'=value->>'id';
  if frozen_container is null then raise exception 'Original frozen container frame required'using errcode='23514';end if;
  if value->'expected_version'='null'::jsonb then
   if not exists(select 1 from public.controlled_stock_containers c where c.id=(value->>'id')::uuid
    and c.created_event_id=e.id and c.opening_id is null and c.product_id=e.product_id
    and c.stock_unit=(select stock_unit from public.controlled_stock_policy_versions where id=e.policy_version_id)
    and c.kind=value#>>'{create,kind}'and c.label=value#>>'{create,label}'
    and c.stock_lot_id is not distinct from(value#>>'{create,stock_lot_id}')::uuid
    and c.controlling_site_id=(value#>>'{create,site_id}')::uuid and c.initial_location_id=(value#>>'{create,location_id}')::uuid
    and c.initial_custodian_id is not distinct from(value#>>'{create,custodian_id}')::uuid
    and c.actor_id=e.actor_id and c.session_id=e.session_id)then
    raise exception 'New physical container must preserve its exact reviewed identity and provenance'using errcode='23514';end if;
  elsif frozen_container->'container'is distinct from(select to_jsonb(c)from public.controlled_stock_containers c where c.id=(value->>'id')::uuid)then
   raise exception 'Existing immutable container differs from its original review'using errcode='23514';end if;
  if not exists(select 1 from public.controlled_stock_container_transitions t where t.event_id=e.id and t.container_id=(value->>'id')::uuid
   and t.before_location_id is not distinct from coalesce(frozen_container#>>'{head,location_id}',value#>>'{create,location_id}')::uuid
   and t.before_custodian_id is not distinct from coalesce(frozen_container#>>'{head,custodian_id}',value#>>'{create,custodian_id}')::uuid
   and t.before_status=coalesce(frozen_container#>>'{head,status}','onsite'))then
   raise exception 'Container transition must begin at its exact frozen reviewed state'using errcode='23514';end if;
  if not exists(select 1 from public.controlled_stock_container_transitions t where t.event_id=e.id and t.container_id=(value->>'id')::uuid
   and t.version_before=coalesce((value->>'expected_version')::bigint,0)
   and jsonb_build_object('status',t.after_status,'location_id',t.after_location_id,'custodian_id',t.after_custodian_id)=value->'after')then
   raise exception 'Immutable container transition differs from its reviewed after-state'using errcode='23514';end if;
  for v in select l as line_value from jsonb_array_elements(value->'lines')l loop
   select coalesce(sum(line.quantity_delta),0)into actual from public.controlled_stock_event_lines line
    join public.controlled_stock_cells c on c.id=line.cell_id
    where line.event_id=e.id and c.container_id=(value->>'id')::uuid and c.lot_id=(v.line_value->>'lot_id')::uuid
     and c.channel=v.line_value->>'channel'and c.dispense_id is not distinct from(v.line_value->>'dispense_id')::uuid
     and c.intake_id is not distinct from(v.line_value->>'intake_id')::uuid;
   if actual is distinct from(v.line_value->>'quantity_delta')::numeric then
    raise exception 'Posted container split differs from its immutable reviewed allocation'using errcode='23514';end if;
  end loop;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('container_id',t.container_id,'version',t.version_after,
  'location_id',t.after_location_id,'custodian_id',t.after_custodian_id,'status',t.after_status,'last_event_id',t.event_id)order by t.container_id),'[]'::jsonb)
 into heads from public.controlled_stock_container_transitions t where t.event_id=e.id;
 if a.receipt is distinct from jsonb_build_object('version',1,'id',e.id,'writer',e.writer,'actor_id',e.actor_id,
  'canonical_result',e.canonical_result,'event',to_jsonb(e),'containers',heads)then
  raise exception 'Owned controlled receipt must preserve the original event and head transitions'using errcode='23514';end if;
end $$;

create function public.controlled_stock_validate_product(p_product uuid)returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare head public.controlled_stock_states;s public.controlled_stock_state_events;opening public.controlled_stock_openings;
 v record;expected numeric;counted bigint;latest bigint;
begin
 select * into head from public.controlled_stock_states where product_id=p_product;
 if head.product_id is null then raise exception 'Ever-managed product must retain its controlled state'using errcode='23514';end if;
 select * into s from public.controlled_stock_state_events where id=head.head_id;
 if s.product_id is distinct from p_product then raise exception 'Controlled state head product mismatch'using errcode='23514';end if;
 select count(*),max(version)into counted,latest from public.controlled_stock_state_events where product_id=p_product;
 if counted<>latest or s.version<>latest or exists(
  select 1 from public.controlled_stock_state_events n left join public.controlled_stock_state_events prior on prior.id=n.prior_event_id
  where n.product_id=p_product and((n.version=1 and(n.state<>'opening_frozen'or n.opening_id is not null))
   or(n.version>1 and(prior.product_id is distinct from p_product or prior.version<>n.version-1 or prior.state='retired'
    or(prior.opening_id is not null and n.opening_id is distinct from prior.opening_id)))))then
  raise exception 'Controlled state must retain its exact initial freeze, ordered history and terminal retirement'using errcode='23514';end if;
 if exists(select 1 from public.controlled_stock_policy_versions policy
  join public.controlled_draft_versions d on d.id=policy.draft_version_id
  join public.controlled_draft_entries entry on entry.id=d.entry_id
  where policy.product_id=p_product and(entry.product_id<>p_product or d.definition->>'product_id'is distinct from p_product::text
   or policy.stock_unit is distinct from d.definition->>'stock_unit'
   or policy.stock_unit is distinct from policy.identity_snapshot->>'unit'))then
  raise exception 'Controlled policy must preserve its exact product classification and stock unit'using errcode='23514';end if;
 select count(*),coalesce(max(sequence),0)into counted,latest from public.controlled_stock_events where product_id=p_product;
 if counted<>latest or latest<>head.event_version
  or(head.last_event_id is not null and not exists(select 1 from public.controlled_stock_events where id=head.last_event_id and product_id=p_product and sequence=latest))then
  raise exception 'Controlled product event sequence projection mismatch'using errcode='23514';end if;
 select * into opening from public.controlled_stock_openings where product_id=p_product;
 if s.opening_id is null then
  if s.state='active'or head.event_version<>0 then raise exception 'An actual opening is required before managed posting'using errcode='23514';end if;
  if opening.id is null then return;end if;
 elsif opening.id is distinct from s.opening_id then
  raise exception 'Exact controlled opening required'using errcode='23514';
 end if;
 -- Persisted openings and current projections are validated even before active
 -- attachment; the immutable boundary uses opening quantities, never latest ones.
 perform public.controlled_stock_validate_opening(opening.id);
 if exists(select 1 from public.controlled_stock_policy_versions policy where policy.product_id=p_product
  and policy.stock_unit is distinct from(select stock_unit from public.controlled_stock_policy_versions where id=opening.policy_version_id))
  or exists(select 1 from public.controlled_stock_containers c where c.product_id=p_product
   and(c.stock_unit is distinct from(select stock_unit from public.controlled_stock_policy_versions where id=opening.policy_version_id)
    or(c.opening_id is not null and c.opening_id<>opening.id)
    or(c.created_event_id is not null and not exists(select 1 from public.controlled_stock_events e where e.id=c.created_event_id and e.product_id=p_product))))then
  raise exception 'Opened controlled stock cannot silently change units or container provenance'using errcode='23514';end if;
 if exists(select 1 from public.inventory_movements m join public.inventory_lots l on l.id=m.lot_id where l.product_id=p_product
  and((select count(*)from public.controlled_stock_opening_movements o where o.movement_id=m.id and o.opening_id=opening.id)
   +(select count(*)from public.controlled_stock_source_links k join public.controlled_stock_events e on e.id=k.event_id
    where k.movement_id=m.id and e.product_id=p_product))<>1)then
  raise exception 'Every movement must belong once to the opening or an exact controlled event'using errcode='23514';end if;
 if exists(select 1 from public.controlled_stock_opening_movements o join public.inventory_movements m on m.id=o.movement_id
  join public.inventory_lots l on l.id=m.lot_id where o.opening_id=opening.id and(o.lot_id<>m.lot_id or o.quantity<>m.quantity
   or l.product_id<>p_product or o.source_snapshot is distinct from to_jsonb(m)))then
  raise exception 'Exact original opening movement membership required'using errcode='23514';end if;
 for v in select c.*,pos.quantity,t.kind,t.stock_lot_id,t.stock_unit,t.product_id from public.controlled_stock_cells c
  join public.controlled_stock_containers t on t.id=c.container_id left join public.controlled_stock_positions pos on pos.cell_id=c.id
  where t.product_id=p_product loop
  select v.opening_quantity+coalesce(sum(l.quantity_delta),0)into expected from public.controlled_stock_event_lines l where l.cell_id=v.id;
  if v.quantity is null or v.quantity<>expected or v.quantity<0
   or not exists(select 1 from public.inventory_lots where id=v.lot_id and product_id=p_product)
   or(v.opening_id is not null and(v.opening_id<>opening.id or not exists(select 1 from public.controlled_stock_containers ct where ct.id=v.container_id and ct.opening_id=v.opening_id)))
   or(v.created_event_id is not null and not exists(select 1 from public.controlled_stock_events e where e.id=v.created_event_id and e.product_id=p_product
    and exists(select 1 from public.controlled_stock_event_lines line where line.cell_id=v.id and line.event_id=e.id)))
   or(v.kind='stock'and(v.channel<>'available'or v.stock_lot_id<>v.lot_id))
   or(v.kind='prepared'and v.channel='available')then
   raise exception 'Exact reconstructible controlled container quantity required'using errcode='23514';end if;
  if v.channel<>'available'and not exists(select 1 from public.native_dispense_allocations a where a.id=v.allocation_id and a.dispense_id=v.dispense_id and a.lot_id=v.lot_id)then
   raise exception 'Physical custody cell requires its actual immutable native allocation'using errcode='23514';end if;
  if v.channel='return_held'and not exists(select 1 from public.native_return_events e where e.id=v.intake_id and e.action='intake'
   and e.dispense_id=v.dispense_id and e.document->>'custody'='clinic_retained')then
   raise exception 'Held controlled cell requires original clinic-retained intake evidence'using errcode='23514';end if;
 end loop;
 for v in select l.id,coalesce(sum(m.quantity),0)balance from public.inventory_lots l left join public.inventory_movements m on m.lot_id=l.id
  where l.product_id=p_product group by l.id loop
  select coalesce(sum(p.quantity),0)into expected from public.controlled_stock_cells c join public.controlled_stock_positions p on p.cell_id=c.id
   join public.controlled_stock_containers t on t.id=c.container_id where t.product_id=p_product and c.lot_id=v.id and c.channel='available';
  if v.balance<>expected then raise exception 'Physical available positions must exactly reconcile to the canonical lot ledger'using errcode='23514';end if;
 end loop;
 if exists(select 1 from public.controlled_stock_container_transitions t
  join public.controlled_stock_containers c on c.id=t.container_id
  left join public.controlled_stock_container_transitions prior on prior.container_id=t.container_id and prior.version_after=t.version_before
  join public.controlled_stock_events e on e.id=t.event_id
  where c.product_id=p_product and(e.product_id<>p_product
   or(t.version_before=0 and(t.before_location_id is distinct from c.initial_location_id
    or t.before_custodian_id is distinct from c.initial_custodian_id or t.before_status<>'onsite'
    or(c.created_event_id is not null and c.created_event_id<>e.id)))
   or(t.version_before>0 and(prior.id is null or t.before_location_id is distinct from prior.after_location_id
    or t.before_custodian_id is distinct from prior.after_custodian_id or t.before_status<>prior.after_status
    or not exists(select 1 from public.controlled_stock_events pe where pe.id=prior.event_id and pe.product_id=p_product and pe.sequence<e.sequence)))))then
  raise exception 'Container transition must preserve its exact predecessor custody and source event'using errcode='23514';end if;
 for v in select c.id,c.initial_location_id,c.initial_custodian_id,c.opening_id,h.version,h.last_event_id,h.location_id,h.custodian_id,h.status
  from public.controlled_stock_containers c left join public.controlled_stock_container_heads h on h.container_id=c.id where c.product_id=p_product loop
  select count(*),coalesce(max(version_after),0)into counted,latest from public.controlled_stock_container_transitions where container_id=v.id;
  if v.version is null or counted<>latest or latest<>v.version then raise exception 'Controlled container transition sequence mismatch'using errcode='23514';end if;
  if latest=0 then
   if v.opening_id is null or v.last_event_id is not null or v.location_id is distinct from v.initial_location_id
    or v.custodian_id is distinct from v.initial_custodian_id or v.status<>'onsite'then
    raise exception 'Opening container head mismatch'using errcode='23514';end if;
  elsif not exists(select 1 from public.controlled_stock_container_transitions t where t.container_id=v.id and t.version_after=latest
   and t.event_id=v.last_event_id and t.after_location_id is not distinct from v.location_id
   and t.after_custodian_id is not distinct from v.custodian_id and t.after_status=v.status)then
   raise exception 'Controlled container head differs from its immutable last transition'using errcode='23514';end if;
  if v.status<>'onsite'and exists(select 1 from public.controlled_stock_cells c join public.controlled_stock_positions p on p.cell_id=c.id where c.container_id=v.id and p.quantity<>0)then
   raise exception 'Released or disposed container cannot retain physical quantity'using errcode='23514';end if;
 end loop;
end $$;

create or replace function public.stock_writer_enter(p_writer text,p_source_id uuid)returns void
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare actor uuid;manifest public.stock_writer_manifests;prior public.stock_writer_admissions;
 reservation public.controlled_stock_preparations;context public.controlled_stock_execution_contexts;has_prior boolean;
begin
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'Stock mutation requires READ COMMITTED isolation'using errcode='23514';end if;
 if p_source_id is null then raise exception 'Stable stock operation required'using errcode='23514';end if;
 actor:=public.clinical_require_staff();
 perform pg_advisory_xact_lock_shared(90271040,0);actor:=public.clinical_require_staff();
 -- Shared with prepare/read/cancel/execute, before every old resource lock.
 perform pg_advisory_xact_lock(hashtextextended('controlled-stock-operation:'||p_source_id::text,0));
 actor:=public.clinical_require_staff();
 if exists(select 1 from public.controlled_stock_policy_versions)then perform public.controlled_stock_manifest_required();end if;
 select * into manifest from public.stock_writer_manifests where writer=p_writer order by version desc limit 1;
 if not found or manifest.definition_sha256 is distinct from encode(sha256(convert_to(pg_get_functiondef(to_regprocedure(manifest.signature)),'UTF8')),'hex')then
  raise exception 'Stock writer coverage changed; reviewed manifest required'using errcode='23514';end if;
 select * into prior from public.stock_writer_admissions where backend_pid=pg_backend_pid()and server_started_at=pg_postmaster_start_time()
  and transaction_id=txid_current()and transaction_started_at=transaction_timestamp()and statement_started_at=statement_timestamp()and actor_id=actor;
 has_prior:=found;
 select * into reservation from public.controlled_stock_preparations where id=p_source_id;
 if found then
  perform public.controlled_stock_actor(actor);context:=public.controlled_stock_current();
  if context.operation_id=p_source_id and context.actor_id=actor and reservation.actor_id=actor
   and context.writer=reservation.writer and(p_writer=context.writer or
    (context.writer='record_anesthesia_drug_administration'and p_writer='record_patient_treatment'and has_prior
     and prior.writer=context.writer and prior.source_id=p_source_id and prior.actor_id=actor))then null;
  elsif reservation.writer=p_writer and reservation.actor_id=actor
   and exists(select 1 from public.controlled_stock_actions where id=p_source_id and actor_id=actor and writer=p_writer)then null;
  else raise exception 'Controlled UUID is reserved; use its owned review and recovery protocol'using errcode='23514';end if;
 end if;
 if has_prior and prior.writer='record_anesthesia_drug_administration'and p_writer='record_patient_treatment'and prior.source_id=p_source_id then
  if reservation.id is not null and(context.operation_id is distinct from p_source_id or context.writer is distinct from prior.writer)then
   raise exception 'Nested controlled treatment requires the actual outer executing context'using errcode='23514';end if;
  return;
 end if;
 insert into public.stock_writer_admissions values(pg_backend_pid(),pg_postmaster_start_time(),txid_current(),transaction_timestamp(),statement_timestamp(),p_writer,p_source_id,actor)
 on conflict(backend_pid)do update set server_started_at=excluded.server_started_at,transaction_id=excluded.transaction_id,
  transaction_started_at=excluded.transaction_started_at,statement_started_at=excluded.statement_started_at,
  writer=excluded.writer,source_id=excluded.source_id,actor_id=excluded.actor_id;
end $$;
create function public.controlled_stock_source_required()returns trigger
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare product uuid;products uuid[];context public.controlled_stock_execution_contexts;
 admission public.stock_writer_admissions;r public.controlled_stock_preparations;
begin
 if TG_TABLE_NAME='inventory_movements'then select product_id into product from public.inventory_lots where id=NEW.lot_id;
 else
  select array_agg(distinct l.product_id)into products from public.native_dispense_allocations a
   join public.inventory_lots l on l.id=a.lot_id where a.dispense_id=NEW.dispense_id;
  if cardinality(products)is distinct from 1 then raise exception 'Exact native source product membership required'using errcode='23514';end if;
  product:=products[1];
 end if;
 -- Ever-managed identity remains covered in frozen/suspended/retired states.
 if not exists(select 1 from public.controlled_stock_policy_versions where product_id=product)then return NEW;end if;
 perform public.controlled_stock_actor();context:=public.controlled_stock_current();admission:=public.stock_writer_current();
 if context.operation_id is null or context.operation_id is distinct from admission.source_id
  or context.writer is distinct from admission.writer or context.actor_id is distinct from admission.actor_id then
  raise exception 'Managed stock requires its actual owned executing context'using errcode='23514';end if;
 select * into r from public.controlled_stock_preparations where id=context.operation_id and actor_id=context.actor_id and writer=context.writer;
 if r.id is null or r.product_id is distinct from product then raise exception 'Managed source does not match its owned product'using errcode='23514';end if;
 if TG_TABLE_NAME<>'inventory_movements'and NEW.id<>r.id then raise exception 'Owned native source UUID mismatch'using errcode='23514';end if;
 perform public.controlled_stock_permission(context.actor_id,r.writer,r.canonical_arguments,r.context);
 return NEW;
end $$;

create function public.read_controlled_stock_action(p_actor_id uuid,p_action_id uuid)returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare actor uuid:=public.controlled_stock_gate(p_actor_id,p_action_id);r public.controlled_stock_preparations;
 receipt jsonb;state text;
begin
 select * into r from public.controlled_stock_preparations where id=p_action_id;
 if not found then return null;end if;
 if r.actor_id<>actor then raise exception 'Controlled action belongs to another staff account'using errcode='42501';end if;
 select a.receipt into receipt from public.controlled_stock_actions a where a.id=r.id and a.actor_id=actor;
 state:=case when receipt is not null then 'saved'
  when exists(select 1 from public.controlled_stock_cancellations where id=r.id)then 'cancelled'
  when r.expires_at<=clock_timestamp()then 'expired'else 'prepared'end;
 return jsonb_build_object('version',1,'id',r.id,'writer',r.writer,'actor_id',r.actor_id,
  'canonical_arguments',r.canonical_arguments,'context',r.context,'frozen',r.frozen,
  'expires_at',r.expires_at,'state',state,'receipt',receipt);
end $$;
create function public.prepare_controlled_stock_action(
 p_actor_id uuid,p_action_id uuid,p_writer text,p_arguments jsonb,p_context jsonb
)returns jsonb language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare actor uuid:=public.controlled_stock_gate(p_actor_id,p_action_id);r public.controlled_stock_preparations;
 product uuid;frozen jsonb;permission jsonb;expected jsonb;request_hash text;
begin
 perform public.controlled_stock_writer(p_writer);
 select * into r from public.controlled_stock_preparations where id=p_action_id;
 if found then
  if r.actor_id<>actor or r.writer<>p_writer or r.canonical_arguments is distinct from p_arguments or r.context is distinct from p_context then
   raise exception 'Controlled operation UUID is permanently bound to its original work'using errcode='23505';end if;
  return public.read_controlled_stock_action(actor,p_action_id);
 end if;
 if public.controlled_stock_root_exists(p_action_id)then
  raise exception 'Existing canonical operation cannot be adopted as a new controlled event'using errcode='23505';end if;
 product:=public.controlled_stock_arguments(p_writer,p_arguments);
 perform public.controlled_stock_product_gate(actor,product);
 perform public.controlled_stock_context(p_writer,p_action_id,p_arguments,p_context);
 permission:=public.controlled_stock_permission(actor,p_writer,p_arguments,p_context);
 frozen:=public.controlled_stock_freeze(actor,p_action_id,p_writer,p_arguments,p_context);
 expected:=public.controlled_stock_check_plan(p_action_id,p_writer,p_arguments,p_context);
 frozen:=frozen||jsonb_build_object('expected_effects',expected,'permission',permission);
 if(select count(*)from public.controlled_stock_preparations pending
  where pending.actor_id=actor and pending.expires_at>clock_timestamp()
   and not exists(select 1 from public.controlled_stock_actions a where a.id=pending.id)
   and not exists(select 1 from public.controlled_stock_cancellations c where c.id=pending.id))>=32 then
  raise exception 'Review pending controlled actions before preparing more work'using errcode='23514';end if;
 perform public.controlled_stock_actor(actor);
 request_hash:=public.controlled_stock_hash(jsonb_build_object('version',1,'actor_id',actor,'id',p_action_id,
  'writer',p_writer,'canonical_arguments',p_arguments,'context',p_context));
 insert into public.controlled_stock_preparations(id,writer,actor_id,session_id,product_id,policy_version_id,state_head_id,opening_id,
  canonical_arguments,context,frozen,request_hash)values(p_action_id,p_writer,actor,public.next_visit_review_session(),product,
  (p_context->>'policy_version_id')::uuid,(p_context->>'state_head_id')::uuid,(p_context->>'opening_id')::uuid,p_arguments,p_context,frozen,request_hash);
 return public.read_controlled_stock_action(actor,p_action_id);
end $$;
create function public.cancel_controlled_stock_action(p_actor_id uuid,p_action_id uuid)returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare actor uuid:=public.controlled_stock_gate(p_actor_id,p_action_id);r public.controlled_stock_preparations;begin
 select * into r from public.controlled_stock_preparations where id=p_action_id;
 if not found then raise exception 'Read the original reviewed controlled action before cancellation'using errcode='PT409';end if;
 if r.actor_id<>actor then raise exception 'Controlled action belongs to another staff account'using errcode='42501';end if;
 if exists(select 1 from public.controlled_stock_actions where id=r.id)then return public.read_controlled_stock_action(actor,r.id);end if;
 if public.controlled_stock_root_exists(r.id)then
  raise exception 'Original canonical outcome requires reconciliation before cancellation'using errcode='PT409';end if;
 if not exists(select 1 from public.controlled_stock_cancellations where id=r.id)then
  insert into public.controlled_stock_cancellations(id,actor_id,writer,session_id)values(r.id,actor,r.writer,public.next_visit_review_session());
 end if;
 return public.read_controlled_stock_action(actor,r.id);
end $$;
create function public.controlled_stock_call_canonical(
 p_id uuid,p_writer text,p_arguments jsonb
)returns jsonb language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare context public.controlled_stock_execution_contexts:=public.controlled_stock_current();result jsonb;begin
 if context.operation_id is distinct from p_id or context.writer is distinct from p_writer then
  raise exception 'Actual owned executing context required for canonical dispatch'using errcode='23514';end if;
 case p_writer
  when 'receive_inventory'then select to_jsonb(public.receive_inventory(p_id,(p_arguments->>'lot_id')::uuid,(p_arguments->>'product_id')::uuid,
   p_arguments->>'lot_number',(p_arguments->>'expires_on')::date,p_arguments->>'location',(p_arguments->>'quantity')::numeric,p_arguments->>'reason'))into result;
  when 'adjust_inventory'then select to_jsonb(public.adjust_inventory(p_id,(p_arguments->>'lot_id')::uuid,(p_arguments->>'quantity')::numeric,p_arguments->>'reason'))into result;
  when 'record_patient_treatment'then select to_jsonb(public.record_patient_treatment(p_id,p_arguments->'request'))into result;
  when 'record_anesthesia_drug_administration'then
   select to_jsonb(public.record_anesthesia_drug_administration(p_id,(p_arguments->>'record_id')::uuid,(p_arguments->>'pet_id')::uuid,p_arguments->'request'))into result;
  when 'record_native_dispense'then result:=public.record_native_dispense(p_id,p_arguments->'request');
  when 'record_native_pickup'then result:=public.record_native_pickup(p_id,p_arguments->'request');
  when 'record_native_dispense_return'then result:=public.record_native_dispense_return(p_id,p_arguments->'request');
  when 'record_native_dispense_return_v2'then result:=public.record_native_dispense_return_v2(p_id,p_arguments->'request');
  when 'record_native_return_discrepancy'then result:=public.record_native_return_discrepancy(p_id,p_arguments->'request');
  when 'append_native_dispense_correction'then result:=public.append_native_dispense_correction(p_id,p_arguments->'request');
  else raise exception 'Reviewed controlled canonical writer required'using errcode='23514';end case;
 return result;
end $$;
create function public.execute_controlled_stock_action(p_actor_id uuid,p_action_id uuid)returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare actor uuid:=public.controlled_stock_gate(p_actor_id,p_action_id);r public.controlled_stock_preparations;
 receipt jsonb;frozen jsonb;permission jsonb;expected jsonb;canonical jsonb;context public.controlled_stock_execution_contexts;
begin
 select * into r from public.controlled_stock_preparations where id=p_action_id;
 if not found then raise exception 'Original reviewed controlled action required'using errcode='PT409';end if;
 if r.actor_id<>actor then raise exception 'Controlled action belongs to another staff account'using errcode='42501';end if;
 -- Saved recovery precedes all catalog/policy/head freshness checks.
 select a.receipt into receipt from public.controlled_stock_actions a where a.id=r.id and a.actor_id=actor;
 if receipt is not null then return receipt;end if;
 if exists(select 1 from public.controlled_stock_cancellations where id=r.id)then
  raise exception 'Controlled action is permanently cancelled; review its saved outcome'using errcode='PT409';end if;
 if r.expires_at<=clock_timestamp()then raise exception 'Controlled review expired; read or explicitly cancel the original work'using errcode='PT409';end if;
 if public.controlled_stock_root_exists(r.id)then raise exception 'Canonical outcome requires investigation before new controlled execution'using errcode='23514';end if;
 perform public.controlled_stock_product_gate(actor,r.product_id);
 permission:=public.controlled_stock_permission(actor,r.writer,r.canonical_arguments,r.context);
 frozen:=public.controlled_stock_freeze(actor,r.id,r.writer,r.canonical_arguments,r.context);
 expected:=public.controlled_stock_check_plan(r.id,r.writer,r.canonical_arguments,r.context);
 frozen:=frozen||jsonb_build_object('expected_effects',expected,'permission',permission);
 if frozen is distinct from r.frozen then raise exception 'Controlled source or container review changed; do not replace the original UUID'using errcode='PT409';end if;
 context:=public.controlled_stock_current();
 if context.operation_id is not null then raise exception 'Finish the current controlled execution before another action'using errcode='23514';end if;
 insert into public.controlled_stock_execution_contexts values(pg_backend_pid(),pg_postmaster_start_time(),txid_current(),transaction_timestamp(),statement_timestamp(),
  gen_random_uuid(),r.id,r.writer,actor,public.next_visit_review_session(),'executing')on conflict(backend_pid)do update set
  server_started_at=excluded.server_started_at,transaction_id=excluded.transaction_id,transaction_started_at=excluded.transaction_started_at,
  statement_started_at=excluded.statement_started_at,nonce=excluded.nonce,operation_id=excluded.operation_id,writer=excluded.writer,
  actor_id=excluded.actor_id,session_id=excluded.session_id,phase=excluded.phase;
 canonical:=public.controlled_stock_call_canonical(r.id,r.writer,r.canonical_arguments);
 receipt:=public.controlled_stock_finish(r.id,canonical);
 delete from public.controlled_stock_execution_contexts where backend_pid=pg_backend_pid()and operation_id=r.id and transaction_id=txid_current();
 perform public.controlled_stock_actor(actor);
 return receipt;
end $$;

create function public.controlled_stock_lock_held(p_namespace text,p_id uuid)returns boolean
language sql volatile set search_path=public,pg_temp set timezone='UTC' as $$
 select exists(select 1 from pg_locks l where l.pid=pg_backend_pid()and l.locktype='advisory'and l.granted and l.mode='ExclusiveLock'and l.objsubid=1
  and l.classid::bigint=((hashtextextended(p_namespace||p_id::text,0)>>32)&4294967295)
  and l.objid::bigint=(hashtextextended(p_namespace||p_id::text,0)&4294967295))
$$;
create function public.controlled_stock_configuration_required()returns uuid
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$declare actor uuid:=public.controlled_stock_actor();begin
 if not exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted
  and classid=90271040 and objid=0 and objsubid=2 and mode='ExclusiveLock')
  or exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted
   and classid=90271040 and objid=0 and objsubid=2 and mode='ShareLock')
  or not exists(select 1 from public.user_roles where user_id=actor and role in('DVM','ADMIN'))then
  raise exception 'Private reviewed exclusive configuration context required'using errcode='23514';end if;
 return actor;
end $$;
create function public.controlled_stock_execution_required(p_id uuid)returns public.controlled_stock_execution_contexts
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$
declare context public.controlled_stock_execution_contexts:=public.controlled_stock_current();r public.controlled_stock_preparations;begin
 perform public.controlled_stock_actor();
 select * into r from public.controlled_stock_preparations where id=p_id;
 if context.operation_id is distinct from p_id or r.id is null or context.actor_id is distinct from r.actor_id
  or context.writer is distinct from r.writer
  or not public.controlled_stock_lock_held('controlled-stock-operation:',p_id)
  or not public.controlled_stock_lock_held('controlled-stock-product:',r.product_id)then
  raise exception 'Exact private owned executing context and ordered gates required'using errcode='23514';end if;
 return context;
end $$;
create function public.controlled_stock_insert_guard()returns trigger
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare j jsonb:=to_jsonb(NEW);context public.controlled_stock_execution_contexts;r public.controlled_stock_preparations;
 actor uuid;root uuid;container public.controlled_stock_containers;cell public.controlled_stock_cells;
begin
 if TG_TABLE_NAME in('controlled_stock_sites','controlled_stock_locations','controlled_stock_policy_versions','controlled_stock_policy_sites',
  'controlled_stock_openings','controlled_stock_opening_movements','controlled_stock_state_events')then
  actor:=public.controlled_stock_configuration_required();
  if j?'actor_id'and(j->>'actor_id')::uuid is distinct from actor then raise exception 'Actual configuration recorder required'using errcode='23514';end if;
  if j?'session_id'and(j->>'session_id')::uuid is distinct from public.next_visit_review_session()then raise exception 'Actual configuration session required'using errcode='23514';end if;
  if TG_TABLE_NAME='controlled_stock_policy_sites'and exists(select 1 from public.controlled_stock_state_events where policy_version_id=(j->>'policy_version_id')::uuid)then
   raise exception 'Published policy site membership requires a new reviewed policy version'using errcode='23514';end if;
  if TG_TABLE_NAME='controlled_stock_opening_movements'and exists(select 1 from public.controlled_stock_state_events where opening_id=(j->>'opening_id')::uuid and state='active')then
   raise exception 'An active opening cannot acquire additional historical movements'using errcode='23514';end if;
  return NEW;
 end if;
 if TG_TABLE_NAME in('controlled_stock_preparations','controlled_stock_cancellations')then
  actor:=public.controlled_stock_actor();root:=(j->>'id')::uuid;
  if(j->>'actor_id')::uuid is distinct from actor or(j->>'session_id')::uuid is distinct from public.next_visit_review_session()
   or not public.controlled_stock_lock_held('controlled-stock-operation:',root)then
   raise exception 'Actual owned reviewed action recorder and gate required'using errcode='23514';end if;
  if TG_TABLE_NAME='controlled_stock_cancellations'and(public.controlled_stock_root_exists(root)
   or exists(select 1 from public.controlled_stock_actions where id=root))then
   raise exception 'Committed or uncertain canonical work cannot be cancelled'using errcode='23514';end if;
  return NEW;
 end if;
 if TG_TABLE_NAME='controlled_stock_cells'then
  select * into container from public.controlled_stock_containers where id=NEW.container_id;
  if NEW.created_event_id is null then
   perform public.controlled_stock_configuration_required();
   if exists(select 1 from public.controlled_stock_state_events where opening_id=NEW.opening_id and state='active')then
    raise exception 'An active opening cannot acquire additional physical cells'using errcode='23514';end if;
   if NEW.opening_id is distinct from container.opening_id then raise exception 'Exact container opening cell required'using errcode='23514';end if;
   return NEW;
  end if;
  root:=NEW.created_event_id;
 elsif TG_TABLE_NAME='controlled_stock_containers'then
  if NEW.created_event_id is null then
   perform public.controlled_stock_configuration_required();
   if exists(select 1 from public.controlled_stock_state_events where opening_id=NEW.opening_id and state='active')then
    raise exception 'An active opening cannot acquire additional containers'using errcode='23514';end if;
   return NEW;
  end if;
  root:=NEW.created_event_id;
 elsif TG_TABLE_NAME in('controlled_stock_events','controlled_stock_actions')then root:=(j->>'id')::uuid;
 else root:=(j->>'event_id')::uuid;end if;
 context:=public.controlled_stock_execution_required(root);
 select * into r from public.controlled_stock_preparations where id=root;
 if j?'actor_id'and(j->>'actor_id')::uuid is distinct from context.actor_id then raise exception 'Actual event recorder required'using errcode='23514';end if;
 if j?'session_id'and(j->>'session_id')::uuid is distinct from context.session_id then raise exception 'Actual executing session required'using errcode='23514';end if;
 if j?'writer'and j->>'writer'is distinct from context.writer then raise exception 'Actual canonical event writer required'using errcode='23514';end if;
 if TG_TABLE_NAME='controlled_stock_actions'and(j->>'request_hash'<>r.request_hash or exists(select 1 from public.controlled_stock_cancellations where id=root))then
  raise exception 'Exact uncancelled owned action receipt required'using errcode='23514';end if;
 return NEW;
end $$;
create function public.controlled_stock_projection_guard()returns trigger
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare context public.controlled_stock_execution_contexts;c public.controlled_stock_cells;t public.controlled_stock_containers;
 product uuid;root uuid;expected numeric;
begin
 if TG_OP in('DELETE','TRUNCATE')then raise exception 'Controlled projections cannot erase evidence'using errcode='23514';end if;
 if TG_TABLE_NAME='controlled_stock_states'then
  if TG_OP='INSERT'then
   perform public.controlled_stock_configuration_required();
   if NEW.event_version<>0 or NEW.last_event_id is not null then raise exception 'New controlled state starts before physical events'using errcode='23514';end if;
   return NEW;
  end if;
  if NEW.product_id<>OLD.product_id then raise exception 'Controlled product identity is immutable'using errcode='23514';end if;
  if NEW.head_id<>OLD.head_id then
   perform public.controlled_stock_configuration_required();
   if NEW.event_version<>OLD.event_version or NEW.last_event_id is distinct from OLD.last_event_id then
    raise exception 'Configuration cannot rewrite physical event heads'using errcode='23514';end if;
   return NEW;
  end if;
  context:=public.controlled_stock_execution_required(NEW.last_event_id);
  if NEW.event_version<>OLD.event_version+1 or not exists(select 1 from public.controlled_stock_events where id=NEW.last_event_id
   and product_id=NEW.product_id and sequence=NEW.event_version and prior_event_id is not distinct from OLD.last_event_id)then
   raise exception 'Guarded next controlled product event required'using errcode='23514';end if;
 elsif TG_TABLE_NAME='controlled_stock_container_heads'then
  select * into t from public.controlled_stock_containers where id=NEW.container_id;
  if TG_OP='INSERT'and NEW.version=0 then
   perform public.controlled_stock_configuration_required();
   if t.opening_id is null then raise exception 'Version-zero head requires its real opening'using errcode='23514';end if;
   return NEW;
  end if;
  context:=public.controlled_stock_execution_required(NEW.last_event_id);
  if TG_OP='UPDATE'and(NEW.container_id<>OLD.container_id or NEW.version<>OLD.version+1)then
   raise exception 'Guarded next immutable container transition required'using errcode='23514';end if;
  if not exists(select 1 from public.controlled_stock_container_transitions where container_id=NEW.container_id and event_id=NEW.last_event_id
   and version_after=NEW.version and after_location_id is not distinct from NEW.location_id
   and after_custodian_id is not distinct from NEW.custodian_id and after_status=NEW.status)then
   raise exception 'Container head must match its actual recorded transition'using errcode='23514';end if;
 elsif TG_TABLE_NAME='controlled_stock_positions'then
  select * into c from public.controlled_stock_cells where id=NEW.cell_id;
  if TG_OP='INSERT'then
   if c.opening_id is not null then
    perform public.controlled_stock_configuration_required();
    if NEW.quantity<>c.opening_quantity then raise exception 'Exact opening position required'using errcode='23514';end if;
   else
    perform public.controlled_stock_execution_required(c.created_event_id);
    if NEW.quantity<>0 then raise exception 'New event cell starts at zero before its exact signed line'using errcode='23514';end if;
   end if;
   return NEW;
  end if;
  if NEW.cell_id<>OLD.cell_id then raise exception 'Physical cell identity is immutable'using errcode='23514';end if;
  context:=public.controlled_stock_current();perform public.controlled_stock_execution_required(context.operation_id);
  select OLD.quantity+coalesce(sum(quantity_delta),0)into expected from public.controlled_stock_event_lines where cell_id=NEW.cell_id and event_id=context.operation_id;
  if NEW.quantity<>expected or NEW.quantity<0 then raise exception 'Position must advance only by its actual signed event lines'using errcode='23514';end if;
 else raise exception 'Unsupported controlled projection'using errcode='23514';end if;
 return NEW;
end $$;
create function public.controlled_stock_execution_guard()returns trigger
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare actor uuid:=public.controlled_stock_actor();r public.controlled_stock_preparations;begin
 if TG_OP='TRUNCATE'then raise exception 'Cannot truncate controlled technical context through an application operation'using errcode='23514';end if;
 if TG_OP='DELETE'then
  if OLD.operation_id is distinct from(public.controlled_stock_current()).operation_id
   or not exists(select 1 from public.controlled_stock_actions where id=OLD.operation_id and actor_id=actor)then
   raise exception 'Only a completely saved owned execution may clear its current context'using errcode='23514';end if;
  return OLD;
 end if;
 select * into r from public.controlled_stock_preparations where id=NEW.operation_id;
 if r.id is null or NEW.actor_id<>actor or NEW.actor_id<>r.actor_id or NEW.writer<>r.writer
  or NEW.session_id<>public.next_visit_review_session()or NEW.backend_pid<>pg_backend_pid()
  or NEW.server_started_at<>pg_postmaster_start_time()or NEW.transaction_id<>txid_current()
  or NEW.transaction_started_at<>transaction_timestamp()or NEW.statement_started_at<>statement_timestamp()
  or NEW.phase<>'executing'or not public.controlled_stock_lock_held('controlled-stock-operation:',r.id)
  or not public.controlled_stock_lock_held('controlled-stock-product:',r.product_id)then
  raise exception 'Actual live owned execution identity and ordered gates required'using errcode='23514';end if;
 if TG_OP='UPDATE'and OLD.backend_pid=pg_backend_pid()and OLD.server_started_at=pg_postmaster_start_time()
  and OLD.transaction_id=txid_current()and OLD.transaction_started_at=transaction_timestamp()then
  raise exception 'A current active execution cannot be overwritten'using errcode='23514';end if;
 return NEW;
end $$;
create function public.controlled_stock_deferred()returns trigger
language plpgsql volatile security definer set search_path=public,pg_temp set timezone='UTC' as $$
declare j jsonb:=to_jsonb(NEW);root uuid;product uuid;v uuid;begin
 if TG_TABLE_NAME='controlled_stock_execution_contexts'then
  if exists(select 1 from public.controlled_stock_execution_contexts where backend_pid=pg_backend_pid()and server_started_at=pg_postmaster_start_time()
   and transaction_id=txid_current()and transaction_started_at=transaction_timestamp())then
   raise exception 'Owned execution context must be cleared before transaction completion'using errcode='23514';end if;
  return null;
 end if;
 if TG_TABLE_NAME in('inventory_movements','native_return_events','native_return_discrepancy_events','native_pickups','native_dispense_correction_events')then
  if TG_TABLE_NAME='inventory_movements'then
   select product_id into product from public.inventory_lots where id=NEW.lot_id;
   select event_id into root from public.controlled_stock_source_links where movement_id=NEW.id;
  else
   select l.product_id into product from public.native_dispense_allocations a join public.inventory_lots l on l.id=a.lot_id where a.dispense_id=NEW.dispense_id limit 1;
   select event_id into root from public.controlled_stock_source_links where coalesce(return_event_id,discrepancy_event_id,pickup_id,correction_event_id)=NEW.id;
  end if;
  if not exists(select 1 from public.controlled_stock_policy_versions where product_id=product)then return null;end if;
  if root is null then raise exception 'Every new managed canonical source requires its exact controlled event'using errcode='23514';end if;
 elsif TG_TABLE_NAME in('controlled_stock_events','controlled_stock_actions')then root:=NEW.id;product:=(select product_id from public.controlled_stock_preparations where id=root);
 elsif TG_TABLE_NAME in('controlled_stock_event_lines','controlled_stock_source_links','controlled_stock_container_transitions')then root:=NEW.event_id;product:=(select product_id from public.controlled_stock_events where id=root);
 elsif TG_TABLE_NAME='controlled_stock_container_heads'then root:=NEW.last_event_id;product:=(select product_id from public.controlled_stock_containers where id=NEW.container_id);
 elsif TG_TABLE_NAME='controlled_stock_positions'then
  select t.product_id into product from public.controlled_stock_cells c join public.controlled_stock_containers t on t.id=c.container_id where c.id=NEW.cell_id;
 elsif TG_TABLE_NAME='controlled_stock_cells'then product:=(select product_id from public.controlled_stock_containers where id=NEW.container_id);
 elsif TG_TABLE_NAME='controlled_stock_containers'then product:=NEW.product_id;
 elsif TG_TABLE_NAME='controlled_stock_cancellations'then
  if exists(select 1 from public.controlled_stock_actions where id=NEW.id)or public.controlled_stock_root_exists(NEW.id)then
   raise exception 'Cancelled controlled UUID cannot also have a canonical commit'using errcode='23514';end if;
 elsif TG_TABLE_NAME='controlled_stock_preparations'then
  if NEW.request_hash<>public.controlled_stock_hash(jsonb_build_object('version',1,'actor_id',NEW.actor_id,'id',NEW.id,
   'writer',NEW.writer,'canonical_arguments',NEW.canonical_arguments,'context',NEW.context))then
   raise exception 'Immutable prepared controlled request hash mismatch'using errcode='23514';end if;
 elsif j?'product_id'then product:=(j->>'product_id')::uuid;
 elsif TG_TABLE_NAME='controlled_stock_policy_sites'then product:=(select product_id from public.controlled_stock_policy_versions where id=NEW.policy_version_id);
 elsif TG_TABLE_NAME='controlled_stock_opening_movements'then product:=(select product_id from public.controlled_stock_openings where id=NEW.opening_id);
 end if;
 if root is not null then perform public.controlled_stock_validate_event(root);end if;
 if product is not null then perform public.controlled_stock_validate_product(product);end if;
 return null;
end $$;

-- Every family below is private. No activation/configuration RPC is granted.
do $$declare r record;name text;columns text;begin
 for r in select c.relname,a.attname,a.atttypid from pg_class c join pg_attribute a on a.attrelid=c.oid
  where c.relnamespace='public'::regnamespace and c.relkind='r'and left(c.relname,17)='controlled_stock_'
   and a.attnum>0 and not a.attisdropped and a.atttypid in('numeric'::regtype,'timestamptz'::regtype,'uuid'::regtype)loop
  if r.atttypid='numeric'::regtype then
   execute format('alter table public.%I add constraint %I check(%I::text not in(''NaN'',''Infinity'',''-Infinity''))',r.relname,'cs_finite_'||r.attname,r.attname);
  elsif r.atttypid='timestamptz'::regtype then
   execute format('alter table public.%I add constraint %I check(isfinite(%I))',r.relname,'cs_finite_'||r.attname,r.attname);
  else execute format('alter table public.%I add constraint %I check(%I<>''00000000-0000-0000-0000-000000000000''::uuid)',r.relname,'cs_nonzero_'||r.attname,r.attname);end if;
 end loop;
 for r in select c.relname from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r'and left(c.relname,17)='controlled_stock_'loop
  name:=r.relname;
  execute format('alter table public.%I enable row level security',name);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',name);
  if name in('controlled_stock_states','controlled_stock_container_heads','controlled_stock_positions')then
   execute format('create trigger controlled_guard before insert or update or delete on public.%I for each row execute function public.controlled_stock_projection_guard()',name);
   execute format('create trigger no_truncate before truncate on public.%I for each statement execute function public.controlled_stock_projection_guard()',name);
  elsif name='controlled_stock_execution_contexts'then
   execute format('create trigger controlled_guard before insert or update or delete on public.%I for each row execute function public.controlled_stock_execution_guard()',name);
   execute format('create trigger no_truncate before truncate on public.%I for each statement execute function public.controlled_stock_execution_guard()',name);
  else
   execute format('create trigger immutable before update or delete on public.%I for each row execute function public.controlled_stock_immutable()',name);
   execute format('create trigger no_truncate before truncate on public.%I for each statement execute function public.controlled_stock_immutable()',name);
   if name<>'controlled_stock_engine_manifests'then
    execute format('create trigger controlled_guard before insert on public.%I for each row execute function public.controlled_stock_insert_guard()',name);
   end if;
  end if;
  if name<>'controlled_stock_engine_manifests'then
   execute format('create constraint trigger controlled_stock_consistency after insert or update on public.%I deferrable initially deferred for each row execute function public.controlled_stock_deferred()',name);
  end if;
 end loop;
 foreach name in array array['inventory_movements','native_return_events','native_return_discrepancy_events','native_pickups','native_dispense_correction_events']loop
  execute format('create trigger controlled_stock_source_required before insert on public.%I for each row execute function public.controlled_stock_source_required()',name);
  execute format('create constraint trigger controlled_stock_source_consistency after insert on public.%I deferrable initially deferred for each row execute function public.controlled_stock_deferred()',name);
 end loop;
 for r in select c.conrelid,c.conkey,c.conname from pg_constraint c join pg_class t on t.oid=c.conrelid
  where c.contype='f'and t.relnamespace='public'::regnamespace and left(t.relname,17)='controlled_stock_'loop
  if not exists(select 1 from pg_index i where i.indrelid=r.conrelid and i.indisvalid and i.indnkeyatts>=cardinality(r.conkey)
   and array(select k.attnum from unnest(i.indkey)with ordinality k(attnum,seq)where k.seq<=cardinality(r.conkey)order by k.seq)=r.conkey)then
   select string_agg(quote_ident(a.attname),','order by k.ordinality)into columns
    from unnest(r.conkey)with ordinality k(attnum,ordinality)join pg_attribute a on a.attrelid=r.conrelid and a.attnum=k.attnum;
   execute format('create index %I on %s(%s)','cs_fk_'||substr(md5(r.conrelid::regclass::text||':'||r.conname),1,24),r.conrelid::regclass,columns);
  end if;
 end loop;
end $$;
create function public.controlled_stock_manifest_snapshot()returns jsonb
language sql volatile set search_path=public,pg_temp set timezone='UTC' as $$
 select jsonb_build_object('version',1,'functions',(
  select jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
   'owner',pg_get_userbyid(p.proowner),'acl',(select jsonb_agg(jsonb_build_object('grantee',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee)end,
    'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable)order by x.grantee::regrole::text,x.grantor::regrole::text,x.privilege_type)
    from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))x),'configuration',to_jsonb(p.proconfig),'definer',p.prosecdef)order by p.oid::regprocedure::text)
  from pg_proc p where p.pronamespace='public'::regnamespace and(
   left(p.proname,17)='controlled_stock_'or left(p.proname,17)='controlled_draft_'or left(p.proname,6)='stock_'
   or p.proname like 'native_rx_%'or p.proname like 'native_fulfillment_%'or p.proname like 'native_return_%'
   or p.proname like 'native_reconciliation_%'or p.proname like 'native_correction_%'
   or p.proname in('read_controlled_stock_action','prepare_controlled_stock_action','execute_controlled_stock_action','cancel_controlled_stock_action',
    'receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup',
    'record_native_dispense_return','record_native_dispense_return_v2','record_native_return_discrepancy','append_native_dispense_correction',
    'clinical_require_staff','is_active_staff','next_visit_review_session','inventory_guard','has_role','protect_profile_privileges',
    'list_controlled_drafts','read_controlled_draft','read_controlled_draft_review','prepare_controlled_draft_review','execute_controlled_draft_review','cancel_controlled_draft_review'))),
 'relations',(
  select jsonb_object_agg(c.relname,jsonb_build_object('rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),
   'acl',(select jsonb_agg(jsonb_build_object('grantee',case when x.grantee=0 then 'PUBLIC'else pg_get_userbyid(x.grantee)end,
    'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable)order by x.grantee::regrole::text,x.grantor::regrole::text,x.privilege_type)
    from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))x),
   'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
    'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))order by a.attnum)
    from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
   'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'permissive',p.polpermissive,'command',p.polcmd,
    'roles',(select jsonb_agg(case when r=0 then 'PUBLIC'else pg_get_userbyid(r)end order by case when r=0 then 'PUBLIC'else pg_get_userbyid(r)end)from unnest(p.polroles)r),
    'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))order by p.polname),'[]'::jsonb)from pg_policy p where p.polrelid=c.oid),
   'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid,true))order by k.conname),'[]'::jsonb)from pg_constraint k where k.conrelid=c.oid),
   'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true))order by t.tgname),'[]'::jsonb)from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),
   'indexes',(select coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid)order by i.indexrelid::regclass::text),'[]'::jsonb)from pg_index i where i.indrelid=c.oid))order by c.relname)
  from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r'and(
   left(c.relname,17)='controlled_stock_'or left(c.relname,17)='controlled_draft_'or left(c.relname,6)='stock_'
   or c.relname in('inventory_movements','inventory_lots','catalog_products','patient_treatments','anesthesia_drug_administrations',
    'native_return_events','native_return_operations','native_return_stock_links','native_return_compensation_links',
    'native_return_discrepancy_events','native_return_discrepancy_operations','native_return_discrepancy_correction_links',
    'native_pickups','native_dispenses','native_dispense_allocations','native_fulfillment_operations',
    'native_dispense_correction_events','native_dispense_correction_operations'))))
$$;
create function public.controlled_stock_manifest_required()returns void
language plpgsql volatile set search_path=public,pg_temp set timezone='UTC' as $$declare m public.controlled_stock_engine_manifests;begin
 select * into m from public.controlled_stock_engine_manifests order by revision desc limit 1;
 if m.revision is null or m.definition_hash<>public.controlled_stock_hash(m.definition)
  or m.definition is distinct from public.controlled_stock_manifest_snapshot()then
  raise exception 'Controlled coverage, code or grants changed; reviewed engine manifest required'using errcode='23514';end if;
end $$;

-- CONTROLLED_RELEASE_AFTER_HOOKS --
do $release_revoke$declare r record;begin
 for r in select p.oid::regprocedure signature from pg_proc p where p.pronamespace='public'::regnamespace
 and(left(p.proname,17)='controlled_stock_'or p.proname in('read_controlled_stock_action','prepare_controlled_stock_action','execute_controlled_stock_action','cancel_controlled_stock_action'))loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);end loop;
end $release_revoke$;
-- CONTROLLED_RELEASE_BEFORE_POSTCHECK --
